quests[30592] = { id = 30592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Trail: To Burlap Waystation", description = "Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine.\n\nCan you help? We are not fighters. We are grummles. Good fortune to those who help grummles.\n\nGo with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives.\n\nGrummles shall reward. Grummles always reward.", sourceObjective = "Protect a group of grummles travelling to the Burlap Waystation. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trail or return to One Keg and wait for the next group to leave.", progress = "Good fortune to friends of grummles.", completion = "Many thanks and fortune to you, friend of grummles. But the journey to the Serpent's Spine is not safe yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30593] = { id = 30593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deanimate the Reanimated", description = "The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting!\n\nThe pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia\n\nWill you help me out, {name}? We can't afford to have a fight with an army of statues right now.", sourceObjective = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", completion = "Alright! Looks like we won't have a bunch of statues to worry about any more. Good work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30594] = { id = 30594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deanimate the Reanimated", description = "I've got much to do here, {name}. I could use your help.\n\nThere's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it.\n\nIf they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.", sourceObjective = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", completion = "Oh, you dealt with the statues? Good work. Here's something for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[30595] = { id = 30595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profiting off of the Past", description = "Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu.\n\nI tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.", sourceObjective = "Collect 12 Mogu Relics.", progress = "Where am I going to be able to put all of the relics?", completion = "Wow! I mean, wow! Thank you, {name}!\n\n\n\nNow that you've softened them up, I'm thinking that I might head in. Just a few more relics from around the outskirts. Nothing dangerous.", sourceObjectiveStatus = "unverified-source-field" }
quests[30596] = { id = 30596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", sourceObjective = "Kill the Zandalari Soulraiser.", sourceObjectiveStatus = "unverified-source-field" }
quests[30597] = { id = 30597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Spherical Stone", description = "This beautiful stone clearly has magical potential... at least to one trained in alchemy.  You are certain that with the right herbs native to Pandaria, this stone could become very useful.", sourceObjective = "Infuse the stone with several Golden Lotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30598] = { id = 30598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Knew Fish Liked Eggs?", description = "Great cranes have been nesting in this area for generations.  The Narsong Spires provide a sheltered area to rear their young.\n\nTheir pristine eggs are revered as bait for catching the silver goby.  Retrieve a crane egg and see if you can catch a goby!", sourceObjective = "Collect a Pristine Egg from the Narsong Spires and use it to catch a Silver Goby.", progress = "Did you catch a silver goby?", completion = "The elusive silver goby!  You truly are becoming an angler {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30599] = { id = 30599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monkey Idol", description = "Before, grummles keep hozen from ravaging by bribing with food.\n\nBut now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices.\n\nThey are using them to kill grummles!\n\nYou must destroy these idols!\n\nFor every idol, there is a chief. Kill the chief and throw the corpse on their altar.", sourceObjective = "Use the Corpses of Tak Tak, Dak Dak, and Ko Ko on their respective altars.", progress = "Hozen are learning that it is most bad fortune to get sacrificed on one's own altar.", completion = "A confident hozen is a dangerous hozen.\n\nThank you for your help, friend of grummles.", sourceObjectiveStatus = "unverified-source-field" }
quests[30600] = { id = 30600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Pack Left Behind", description = "The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered.\n\nFortune frowns on a grummlepack undelivered.\n\nPlease, give my grummles peace on the great trail of beyond and bring their grummlepacks to me.\n\nI will see they are delivered.", sourceObjective = "Recover 8 Grummlepacks from Camp Broketooth or The Deeper.", progress = "Grummles are a simple people. We are made to explore and deliver.", completion = "You are good fortune for grummles.\n\nWhen we are back at a proper camp I must buy you the smelliest, luckiest incense I can find.", sourceObjectiveStatus = "unverified-source-field" }
quests[30601] = { id = 30601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instant Courage", description = "It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there.\n\nGrummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way.", sourceObjective = "Inspire 3 Hiding Guides in Howlingwind Cavern to help you.", completion = "Incense works like a charm! Effects will not last long, so you must hurry!", sourceObjectiveStatus = "unverified-source-field" }
quests[30602] = { id = 30602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rabbitsfoot", description = "The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo.\n\nThis is very bad fortune indeed. Please, {race}, we need our Rabbitsfoot back. We need his good fortune back.\n\nCan you search the Broketooth Outpost for him?", sourceObjective = "Rescue Brother Rabbitsfoot from the Broketooth Outpost.", completion = "Look what Broketooths and Knucklethumps did to grummle waystation. Hardly a luckydo to be found.\n\nGrummles had a deal with the hozen. We give them food, and they don't ravage. Whenever they think to ravage, Shado-Pan remind them not to ravage.\n\nBut all of Shado-Pan are away defending the wall now. And the hozen want more food than the grummles have.", sourceObjectiveStatus = "unverified-source-field" }
quests[30603] = { id = 30603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broketooth Ravage", description = "They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot.\n\nThis is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost.\n\nPlease can you get it back?", sourceObjective = "Retrieve Rabbitsfoot's Luckydo from Mo Mo.", progress = "Grummles named for the luckydo that gives the most fortune to specific grummle. It is most important that hozen not steal a grummle's luck.", completion = "My luckydo! Oh happy day of good fortune! Many thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[30604] = { id = 30604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Broketooth", description = "Hozen only ravage when they think their supplies are too few for their number of mouths.\n\nProblem is, hozen always have more mouths than food.\n\nWe have very few grummles these days.\n\nIt is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.", sourceObjective = "Kill 8 Broketooth Chargers and 6 Broketooth Tossers.", completion = "Thank you, {name}! Hopefully that will slow the Broketooth ravage.", sourceObjectiveStatus = "unverified-source-field" }
quests[30605] = { id = 30605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lucky Yakshoe", sourceObjective = "Rescue Brother Yakshoe.", completion = "Good fortune for me to be saved by a luckydo like you.\n\nAnd Brother Rabbitsfoot always say I not have good fortune. Bah!", sourceObjectiveStatus = "unverified-source-field" }
quests[30606] = { id = 30606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thumping Knucklethump", description = "The Knucklethump hozen have new chief, the Ook of Dook.\n\nHe sees fear in the west, anger in the south, hatred in the north, and yaungols in the east.\n\nAnd so he sets his hozen to ravage, gathering food and supplies for coming famine.\n\nThey are many Knucklethumps and dangerous.\n\nPlease, Luckydo, can you defeat their fighters?", sourceObjective = "Slay 8 Knucklethump Smashers or Jibstabbers at Knucklethump Hole.", progress = "It is sad so many hozen must die.", completion = "You are a true luckydo.", sourceObjectiveStatus = "unverified-source-field" }
quests[30607] = { id = 30607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen Love Their Keys", description = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave.\n\nHozen are normally scared of yeti, but now they feed it grummles.\n\nThey have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles?\n\nBad fortune for hozen if a yeti is loose in their fort.", sourceObjective = "Get the Yeti Shackle Key from Cho Cho the Wicked and release Old Poot Poot.", progress = "A luckydo would be wise to never travel near a yeti on a dirty yak.", completion = "Oh wow that looked like one wild ride!", sourceObjectiveStatus = "unverified-source-field" }
quests[30608] = { id = 30608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Snackrifice", description = "They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti.\n\nPlease rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can.\n\nMany fortunes and rewards if you do this.", sourceObjective = "Rescue 5 Imprisoned Grummles by cutting them down or releasing them from cages.", completion = "Today is a day of many good and bad fortunes. Bad fortune that hozen stole my grummles. Good fortune that my {race} saves my grummles. Bad fortune that so many hozen must die to learn lesson. Good fortune that {race} are luckydos and know how to fight.\n\nGrummles are not fighters. We carry, we explore, and we are content.", sourceObjectiveStatus = "unverified-source-field" }
quests[30610] = { id = 30610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grummle! Grummle! Grummle!", description = "Now that grummles are rescued, we need to rescue our supplies.\n\nThe Ook of Dook is only chief because he has supplies.\n\nGo to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates.\n\nGrummles know what to do from there.\n\nRabbitsfoot and I will meet you there.", sourceObjective = "Lead 5 Packless Grummles to Supply Crates near the Dooker Dome.", progress = "Grummles are good at carrying things.", completion = "Now that hozen king is going to learn why it is bad fortune to cheat grummles.", sourceObjectiveStatus = "unverified-source-field" }
quests[30611] = { id = 30611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash The Yeti!", description = "Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp.\n\nHe uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti.\n\nGo to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much.\n\nYakshoe and I will meet you there with lots of incense and a dirty yak.", sourceObjective = "Kill 4 Cagemasters.", progress = "We found a yak. Did you take out some hozen?", completion = "Ready for the yeti?", sourceObjectiveStatus = "unverified-source-field" }
quests[30612] = { id = 30612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leader Hozen", description = "The time has come to face the Ook of Dook. We beat him, and the hozen won't have someone telling them to ravage.\n\nHere is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp.\n\nThen, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home.\n\nWe'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.", sourceObjective = "Enrage Chomp Chomp and then defeat the Ook of Dook.", completion = "The Ook of Dook is dead! Hurray!", sourceObjectiveStatus = "unverified-source-field" }
quests[30613] = { id = 30613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored Carp", description = "Armored Carp are a delicacy around these parts.\n\nUnfortunately we can't fish them up since they snap our hooks with their powerful jaws.  Take this fishing spear and see if you can catch a few for us.", sourceObjective = "Use the Fishing Spear to catch 5 Armored Carp in the waters south of Anglers Wharf.", progress = "Any luck with that fishing spear?", completion = "Careful with that carp, {name}.  They have been known to bite fingers off!", sourceObjectiveStatus = "unverified-source-field" }
quests[30614] = { id = 30614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oil Stop", description = "When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know.\n\nHere, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.", sourceObjective = "Fill the Empty Oil Vial at a Yaungol Oil Derrick.", progress = "Yaungols are scary. Yaungols with a luckydo like this \"oil\" are more scary.", completion = "Happy day! Your reward. May these coins bring you good fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[30615] = { id = 30615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", sourceObjective = "Kill the Zandalari Soulraiser.", sourceObjectiveStatus = "unverified-source-field" }
quests[30616] = { id = 30616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traffic Issues", description = "Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles.\n\nWe use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger.\n\nGrummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?", sourceObjective = "Defeat 8 Fire Camp Ruqin Yaungols.", completion = "It is good fortune that a {race} comes to help grummles. Good fortune to friend of grummles.", sourceObjectiveStatus = "unverified-source-field" }
quests[30617] = { id = 30617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roadside Assistance", description = "A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better.\n\nCan you journey up the road to One Keg and light the incense you find along the way?\n\nThis will give good fortune to grummles that must travel the road.\n\nBrother Lintpocket can give you many rewards. Speak to him when you arrive.", sourceObjective = "Light 8 Lucky Burlap Incense sticks along the road to One Keg.", completion = "Welcome to One Keg! Gateway to Burlap Trail and Mount Neverest.", sourceObjectiveStatus = "unverified-source-field" }
quests[30618] = { id = 30618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying One Keg", description = "If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you..\n\nOh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level.\n\nIf you could help me recover some of my supplies I should have enough to contribute to your journey.", sourceObjective = "Recover 8 Stolen Supplies from Howlingwind Cavern.", progress = "Did you manage to get some of my supplies back?", completion = "Oh thank you, {name}! If I just cut off the nibbled pieces and repair the minor damage, I may still be able to sell these.\n\nOnce your cart is ready to go I'll have the supplies I promised loaded up!", sourceObjectiveStatus = "unverified-source-field" }
quests[30619] = { id = 30619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!", sourceObjective = "Kill the Mogujia Soul-Caller.", progress = "Did you find him? Is he dead? No? Oh, man. Don't make me worried!", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years.", sourceObjectiveStatus = "unverified-source-field" }
quests[30620] = { id = 30620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say Mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!", sourceObjective = "Kill the Mogujia Soul-Caller.", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years.", sourceObjectiveStatus = "unverified-source-field" }
quests[30621] = { id = 30621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Stole My Luck!", description = "My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by.\n\nThe grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it!\n\nAfter arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.", sourceObjective = "Return Ji-Lu the Lucky's Lucky Virmen's Foot, Yak Shoe, Four Winds Clover, and Gold Coin.", progress = "Were you able to find my lucky trinkets? One can never have too much good luck.", completion = "Thank you! It appears my trinkets were lucky for you too, {class}. While you were gone I did not gamble and lose my cart.\n\nI would be happy to lend it to you for your journey. Besides, I have some goods to win back from this shady grummle!", sourceObjectiveStatus = "unverified-source-field" }
quests[30622] = { id = 30622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swarm Begins", description = "Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer.\n\nCheck in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there.\n\nIf we win, we win. If we lose, we go down fighting. For Pandaria!", sourceObjective = "Slay 15 Ik'thik Warriors or Ik'thik Infestors.", progress = "Look at the SIZE of that thing...", completion = "My wall... I spent my life atop that wall...", sourceObjectiveStatus = "unverified-source-field" }
quests[30623] = { id = 30623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantidote", description = "<Mei motions towards the battlefield.>\n\nYou see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch.\n\nPerhaps... they're under the influence of the sha, too?\n\nI kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.", sourceObjective = "Use Ken-Ken's Mask on 5 Ik'thik Wing Commanders, then defeat the Manifestations of Fear that come out.", sourceObjectiveStatus = "unverified-source-field" }
quests[30624] = { id = 30624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", sourceObjective = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the night elf settlers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30625] = { id = 30625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students No More", description = "Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left.\n\nThere's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.", sourceObjective = "Find the martial arts students, then help them defeat an Ik'thik Bloodrager, Egg-Matron, Tendon-Slicer, and Fearmonger.", completion = "They can't keep fighting like this forever. Those kids are downright heroic, but I don't want them to die as heroes.\n\nIt's time to throw in the towel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30626] = { id = 30626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retreat!", description = "I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai's to make.\n\nYou go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.", sourceObjective = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", completion = "I see.\n\nWell, we gave it our all. It's time to evacuate, save lives, and reassess our strategy, before these mantid take over the entire valley.", sourceObjectiveStatus = "unverified-source-field" }
quests[30627] = { id = 30627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savior of Stoneplow", description = "That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU.\n\n\"But it's too hard,\" you might say.\n\nYou would be wrong. It is not too hard. NOTHING IS TOO HARD.\n\nGo now, {name}. Go, and save Stoneplow!", sourceObjective = "Speak with Miss Fanny at Stoneplow. Then, with her help, defeat the Mantid Colossus.", progress = "All is lost, {name}. Pack up your things. We're headed to Halfhill.", completion = "I can't believe it! You - a foreign-born {race} - have succeeded where the Shado-Pan have failed. You've succeeded where the WALL has failed.\n\nWe may hold this farming village after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[30628] = { id = 30628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gratitude of Stoneplow", description = "One last thing, {name}. Don't worry, it's not another favor. You've killed enough mantid today.\n\nWe recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.", sourceObjective = "Find the Commander's Cache and collect your reward.", completion = "Peering inside, you find...", sourceObjectiveStatus = "unverified-source-field" }
quests[30630] = { id = 30630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Matron Vi Vinh at the Shrine of Seven Stars.\n\nShe should be able to settle you in.", sourceObjective = "Speak to Matron Vi Vinh at the Shrine of Seven Stars in the Vale of Eternal Blossoms.", sourceObjectiveStatus = "unverified-source-field" }
quests[30631] = { id = 30631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Seven Stars", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.", sourceObjective = "Speak to Jaluu the Generous, Kuru the Light-Hearted, Lucky Lin, and Matron Vi Vinh in the Vale of Eternal Blossoms.", progress = "The cities are springing back to life.", completion = "Good work, {name}. It sounds as though they are getting on quite well at the city.\n\nHowever, in order to ensure their safety, we must be even more vigilant than before.", sourceObjectiveStatus = "unverified-source-field" }
quests[30632] = { id = 30632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "According to Zhi the Harmonious, the mogu are moving into the Vale from the Ruins of Guo-Lai to the west.\n\nI sent Anji and Kun to investigate the situation, but they have not yet returned.\n\nI need a capable {class} like you to go check on them.", sourceObjective = "Speak to Anji Autumnlight at the Ruins of Guo-Lai in the Vale of Eternal Blossoms.", completion = "Leven sent you? I hope you're ready for a fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[30633] = { id = 30633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out with the Scouts", description = "We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated.\n\nScouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures.\n\nYour objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.", sourceObjective = "Kill 8 Shao-Tien Precursor.", progress = "Are the scouts taken care of?", completion = "Well done, {race}. That should send a clear message to the mogu - we are not to be trifled with.", sourceObjectiveStatus = "unverified-source-field" }
quests[30634] = { id = 30634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barring Entry", description = "Lao Softfoot and I scouted up the ruins to the north.\n\nIt looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through.\n\nThere are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins.\n\nHe'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave.\n\nThe rest should take care of itself.", sourceObjective = "Speak to Lao Softfoot at the entrance to Ruins Rise and follow him up the trail. Then, plant the Explosive Keg at the Ruins Rise Cave Entrance.", progress = "Is the cave closed?", completion = "Wonderful, {name}!\n\nYou and Lao have single-handedly crippled the mogu advance.\n\nThat is called working smarter, not harder.", sourceObjectiveStatus = "unverified-source-field" }
quests[30635] = { id = 30635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Quilen", description = "We've taken care of the scout problem for now, but there are still advance mogu forces inside the Guo-Lai Halls down the hill.\n\nUnfortunately, their vicious guard dogs are protecting their operations deeper in the ruins.\n\nGo and dispatch of their beasts. Be on your guard - they can be quite good at blending into their surroundings.", sourceObjective = "Kill 9 Stone Guardians.", completion = "Good. Those dogs know no mercy, so it's good that you showed them none.", sourceObjectiveStatus = "unverified-source-field" }
quests[30636] = { id = 30636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Power", description = "Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite.\n\nWith this substance, they were able to power cities, factories, and engines of war.\n\nZhi the Harmonious has asked us to collect some crystals and bring them back to the city.\n\nKeep an eye out for them while you are in the ruins.", sourceObjective = "Collect 7 Revelite Crystals.", progress = "Did you find the crystals?", completion = "Mmmhmm. These will do nicely.\n\nI'll have them sent back to camp immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[30637] = { id = 30637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guo-Lai Halls", description = "As you pass by the great door, you hear sounds from deep inside.\n\nAnji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below.\n\nYour senses tingling, you decide to investigate.", sourceObjective = "Investigate the mogu presence in the Guo-Lai Halls.", progress = "What did you find in the Halls?", completion = "Your instincts were correct, {name}.\n\nIn ancient times, the Guo-Lai Halls were home to powerful treasures.\n\nWe must do everything we can to stop this mogu warlord from accessing those sealed crypts.", sourceObjectiveStatus = "unverified-source-field" }
quests[30638] = { id = 30638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaving an Opening", description = "This is serious.\n\nKun and I will keep an eye on things here, but you should go to the Golden Pagoda.\n\nGo, swiftly!", sourceObjective = "Speak to Leven Dawnblade at the Golden Pagoda in the Vale of Eternal Blossoms.", completion = "To arms, {name}! I thought we would have more time to set up our defenses, but the mogu are proving to be a deadly and intelligent enemy.\n\nWe've moved the refugees and our supplies into the city behind us.\n\nIt's up to us to protect the front. We must not let the mogu gain a single foothold here in the Vale.", sourceObjectiveStatus = "unverified-source-field" }
quests[30639] = { id = 30639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Guo-Lai", description = "I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them.\n\nHe Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers.\n\nMove quickly, {name}. I don't like the thought that the mogu may be a step ahead of us.", sourceObjective = "Meet with He Softfoot in the Guo-Lai Halls and uncover the mogu's purpose in the western chamber.", progress = "What are you waiting for? Find He. Stop the Shao-Tien!", completion = "The Shao-Tien were spotted marching out of the halls with a hundred jade statues. The mogu now have an immense jade army to turn against us, and we've yet to uncover their other goals in the Vale. We are all in danger.\n\nI had thought you and He dead. It's good that I was mistaken on the last part at least. Rest. Recover. There will be much fighting ahead.", sourceObjectiveStatus = "unverified-source-field" }
quests[30640] = { id = 30640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Spear of the Thunder King", description = "I have received some troubling news, {name}.\n\nThe mogu are plotting to steal three artifacts of power from the Vale.\n\nWe must retrieve the artifacts immediately and hide them for safekeeping.\n\nThe first artifact is the Battle Spear of the Thunder King.\n\nUpon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest.\n\nBring the spear back to me.", sourceObjective = "Retrieve the Battle Spear of the Thunder King.", progress = "It was said that the most powerful of ancient mogu could call the powers of the elements.\n\nThe Thunder King himself could channel the forces of lightning onto his spear.", completion = "Well done, {name}, although it pains me to lay my eyes upon that wretched spear.\n\nThis foul weapon murdered thousands of innocents.\n\nAs long as I live, the mogu shall never have possession of it again.", sourceObjectiveStatus = "unverified-source-field" }
quests[30641] = { id = 30641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Helm of the Thunder King", description = "The second artifact of power is the Battle Helm of the Thunder King.\n\nEmperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it.\n\nWhen the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers.\n\nThus, they could look upon their leader and follow him into death.", sourceObjective = "Retrieve the Battle Helm of the Thunder King.", progress = "History claims that Lei Shen feared no enemy except for one. And in the end, it was death that finally defeated him.", completion = "Thank you, {name}.\n\nWhile our soldiers fight the mogu on the battlefield, I work to strip away the power of their legends.\n\nIn time, Lei Shen shall be no more than the shadow of a memory.", sourceObjectiveStatus = "unverified-source-field" }
quests[30642] = { id = 30642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Axe of the Thunder King", description = "The final artifact is the Thunder King's axe.\n\nLei Shen charged into battle with his spear in one hand, and his axe in the other.\n\nIt is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder.\n\nAfter his death, the axe was placed in a ceremonial chamber to the southwest.\n\nNeedless to say, we must not let it fall into the mogu's hands.", sourceObjective = "Retrieve the Battle Axe of the Thunder King.", progress = "Did you find the axe?", completion = "Such modesty, {name}. I witnessed what you did to retrieve the axe. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[30643] = { id = 30643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu's Message", description = "The battle against the mogu rages fiercely with neither side giving quarter.\n\nWe cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover.\n\nGo check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.", sourceObjective = "Speak to Zhi the Harmonious at The Silent Sanctuary in the Vale of Eternal Blossoms.", completion = "Zhi the Harmonious and the defenders were slaughtered mercilessly.\n\nYour senses tingle. You realize that the Thunder King's treasures are gone!", sourceObjectiveStatus = "unverified-source-field" }
quests[30644] = { id = 30644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Comes to Pass", description = "You had better report back to the Golden Pagoda immediately.", sourceObjective = "Speak to Sun Tenderheart at the Golden Pagoda in the Vale of Eternal Blossoms.", completion = "What? Zhi the Harmonious... is dead? Oh...\n\nYou did very well, given the circumstances. I'm sure a lesser {class} would have succumbed to those assassins.\n\nThings are happening... so quickly. We must all keep ourselves together.", sourceObjectiveStatus = "unverified-source-field" }
quests[30645] = { id = 30645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Three", description = "This is it, {name}. This is the end.\n\nIf we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will.\n\nBut our forces are few, and tired, and small. We bleed, while their warriors are made of stone.\n\n{name}, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders.\n\nI have prayed to the Celestials, begging their aid. I can only hope that they answer our call.", sourceObjective = "Slay 100 mogu invaders at the Summer Fields in the Vale of Eternal Blossoms.", completion = "What? You have slain how many mogu?\n\nRemarkable! If we survive this, you must tell me everything that happened.", sourceObjectiveStatus = "unverified-source-field" }
quests[30646] = { id = 30646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Power", description = "I never thought it would come to this!\n\nLeven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through!\n\nWe are the only ones who stand between him and the Vale's greatest... and most deadly... powers.\n\nPlease, {name}, you must find a way to stop him!", sourceObjective = "Kill Warlord Zhao-Jin the Bloodletter.", completion = "What you have accomplished today will live on in stories for ages to come.\n\nWith your help, we have saved the Vale from a terrible enemy.\n\nToday, we dealt a painful blow to the mogu. They will never stop their attempts to seize the Vale, but it will be a long time before they try a full scale attack again.", sourceObjectiveStatus = "unverified-source-field" }
quests[30648] = { id = 30648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving On", description = "Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time.\n\nA chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence.\n\nFor now it is wisest that you leave this place and explore Pandaria's other regions.\n\nSpeak to me when you are ready to leave.", sourceObjective = "Speak to Fei and travel to Valley of the Four Winds.", sourceObjectiveStatus = "unverified-source-field" }
quests[30649] = { id = 30649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Two Moons", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.", sourceObjective = "Speak to Jaluu the Generous, Mokimo the Strong, Elder Liao, and Madam Vee Luo in the Vale of Eternal Blossoms.", progress = "The cities are springing back to life.", completion = "Good work, {name}. The city should be safe for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[30650] = { id = 30650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Prisoners", description = "Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance.\n\nWhat do you say, {name}?", sourceObjective = "Free 8 Pandaren Prisoners.", completion = "Well, if it isn't our hero, {name}.\n\nI really wasn't sure we stood a fighting chance out here, you know?\n\nThese guys may be a little rough around the edges, but we'll be able to whip 'em into shape. And when we do, we'll have a real fighting chance at holding our own here in Kun-Lai.\n\nGood work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30651] = { id = 30651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels of Fun", description = "Oh, well now, let's have us some fun, <boyo/girly>!\n\nThose Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there.\n\nLet's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?", sourceObjective = "Use Explosive Barrels found in Fire Camp Ordo to destroy the West, South, and East Oil Rigs.", completion = "Ho ho, that were a fine sight to see. I knew I should have gone up there with ya, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30652] = { id = 30652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader.\n\nUnfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", sourceObjective = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.", sourceObjectiveStatus = "unverified-source-field" }
quests[30653] = { id = 30653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", sourceObjective = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the tauren settlers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30654] = { id = 30654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guo-Lai Halls", description = "The mogu are up to something, I can feel it.\n\nThey've been sending scouts down into the Guo-Lai Halls.\n\nAccording to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power.\n\nWe must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!", sourceObjective = "Investigate the mogu presence in the Guo-Lai Halls.", completion = "It looks like you may have averted a great disaster, {name}.\n\nIf this mogu warlord seeks the treasures of the Guo-Lai Halls, we must do all that we can to stop him.", sourceObjectiveStatus = "unverified-source-field" }
quests[30655] = { id = 30655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Prisoners", description = "Look, I know the Horde needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Horde.\n\nWhat do you say, {name}?", sourceObjective = "Free 8 Pandaren Prisoners.", completion = "Well, it looks like we've got ourselves a little army, here, thanks to you.\n\nThey may not look like much yet, but a little Horde discipline and we'll have them in fighting shape in no time.\n\nBy the way, {name}... good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30656] = { id = 30656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels of Fun", description = "I love blowing stuff up. It's in my blood!\n\nThe yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around.\n\nI say we put them to good use and destroy their oil-pumpin' machines while having some fun!", sourceObjective = "Use Explosive Barrels found in Fire Camp Ordo to destroy the East, South, and West Oil Rigs.", completion = "You can't tell me that wasn't fun, {name}! I knew I should have gone over there with you!", sourceObjectiveStatus = "unverified-source-field" }
quests[30657] = { id = 30657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader.\n\nThe coward is hiding in a cave, which is protected by a fire shield cast by his four underlings.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", sourceObjective = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.", sourceObjectiveStatus = "unverified-source-field" }
quests[30658] = { id = 30658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huff & Puff", description = "Have you heard of the prickly puffer fish {name}?  Of course you haven't, you're new around these parts!\n\nThey can be found in the sarjun depths, due west of here.  Take this fishing spear and see if you can bring me back of few of their poison tipped spines.", sourceObjective = "Use the Fishing Spear to kill 5 Prickly Puffer fish in Sarjun Depths and return with their spines.", progress = "Careful with that spear, {name}.", completion = "Ahh, I see you recovered some spines {name}.  These will certainly work well on my spear tips!", sourceObjectiveStatus = "unverified-source-field" }
quests[30660] = { id = 30660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo yaungol!>", sourceObjective = "Kill Ordo Warbringer.", completion = "You've done it, {name}! I'm in your debt!\n\nAgain!", sourceObjectiveStatus = "unverified-source-field" }
quests[30661] = { id = 30661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo!>", sourceObjective = "Kill the Ordo Warbringer.", progress = "Wait, what are you doing here, {name}? I'd heard that the Ordo Warbringer isn't dead yet!", completion = "Once again you've accomplished what no one else could.\n\nWas there any doubt?", sourceObjectiveStatus = "unverified-source-field" }
quests[30662] = { id = 30662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Go back there before the shield goes up again.\n\nTime to head into the cave and slay their chief!", sourceObjective = "Kill the Ordo Warbringer.", completion = "You've done it, {name}! I'm in your debt!\n\nAgain!", sourceObjectiveStatus = "unverified-source-field" }
quests[30663] = { id = 30663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again.\n\nSlay the Warbringer of the Ordo!", sourceObjective = "Kill the Ordo Warbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30665] = { id = 30665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Shado-Pan Fallback", description = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town.\n\nA few lucky villagers may have survived, but we are pinned down here.\n\nWe do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.", sourceObjective = "Kill 15 Sha-Infested Yaungol.", completion = "You have bought us some time to breathe. We must not despair - instead, we must act.", sourceObjectiveStatus = "unverified-source-field" }
quests[30666] = { id = 30666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sudden, Unexpected Crocolisk Aggression", description = "Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities.\n\nYou look like a handy {class}. Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.", sourceObjective = "Slay 8 Mortbreath crocolisks at Kea Krak.", completion = "Yesterday, we were fishing happily. Today, the crocs just started... tryin' to eat us.\n\nStrange.", sourceObjectiveStatus = "unverified-source-field" }
quests[30667] = { id = 30667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Particular Plumage", description = "When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest.\n\nI can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles.\n\nYou up for some feather hunting?", sourceObjective = "Obtain 6 Emerald Tailfeathers, 6 Crimson Tailfeathers, and 6 Dusky Tailfeathers.", progress = "<A bead of sweat twinkles in the fur above Tony's brow.>", completion = "Thanks, {name}. You've made my day. I always hate to see such a prime feather-gathering opportunity go to waste.", sourceObjectiveStatus = "unverified-source-field" }
quests[30668] = { id = 30668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build Your Own Raft", description = "<Jay looks off in the direction of Kea Krak.>\n\nHmm. They don't seem to be... calming down. We're going to have to try something different.\n\nYou'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.", sourceObjective = "Obtain 4 Spare Planks and some Tough Kelp.", progress = "You got the stuff? I'll build your raft, I just need materials.", completion = "<Jay deftly weaves the planks together into a surprisingly seaworthy-looking vessel, then tosses them down into water below.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30669] = { id = 30669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalker on the Lake", description = "Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana  Wu.\n\nWhenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.", sourceObjective = "Board your raft, then report to Wise Ana Wu in the middle of Nayeli Lagoon.", completion = "You appear troubled, child.\n\nHow can this Lorewalker serve you? What is it that you seek?", sourceObjectiveStatus = "unverified-source-field" }
quests[30670] = { id = 30670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turnabout", description = "Our true enemies are the sha, not the yungol.\n\nThe sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel.\n\nAnd, discipline and wisdom can turn their destructive energy against themselves.\n\nBring me the essences of the sha in the village, and I will explain further.", sourceObjective = "Collect 5 Blind Rage Essences from Blind Rages in Firebough Nook.", progress = "Have you harvested their essences?", completion = "Good. Now you will see how to defeat unbridled rage.\n\nI will craft these into a trap for Kobai, the leader of the yaungol. Though he will be snared, and we will defeat him, he is not our ultimate target...", sourceObjectiveStatus = "unverified-source-field" }
quests[30671] = { id = 30671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom Has A Price", description = "<Ana listens to your story, and nods.>\n\nCrocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry.\n\nShark meat should do the trick. You should find enough sharks in the water beneath us.", sourceObjective = "Obtain 5 Shark Fillets.", progress = "My hunger is great, {race}. I have been on this lagoon for several days, without food.", completion = "You've brought me more meat than I could ever hope to eat.\n\nNow, I suppose I owe you a story...", sourceObjectiveStatus = "unverified-source-field" }
quests[30672] = { id = 30672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance", description = "The story did not end happily. The Narsong crocolisk is no more.\n\nThis time, however, you may have a chance to change the ending.\n\nThe hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista.\n\nGo now, {race}! Stop those hozen from their reckless fishing!", sourceObjective = "Slay 10 Unga Fish-Getters.", completion = "<Jay listens to your account of the day's events.>\n\nI see. We'll keep an eye on the Ungas from here. And we'll do our best not to fish these waters too heavily, either. No doubt we're part of the problem, too.\n\nUntil next time, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30673] = { id = 30673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Thank the heavenly spirits for you, {class}! I don't know how much longer I could've lasted.\n\nThere are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?", sourceObjective = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30674] = { id = 30674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Without Violence", description = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.", sourceObjective = "Throw 6 Flailing Carp into Nayeli Lagoon.", sourceObjectiveStatus = "unverified-source-field" }
quests[30675] = { id = 30675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Hozen Treasure", description = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach.\n\nIs there buried treasure somewhere on this island?", sourceObjective = "Find the Buried Hozen Treasure.", sourceObjectiveStatus = "unverified-source-field" }
quests[30677] = { id = 30677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shuttle Service" }
quests[30678] = { id = 30678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Bombing Fish In A Barrel", description = "Turns out these rays are not as easy to catch as I thought!  You seem like a pretty smart guy, think you can help me out?\n\nI made the bombs but have been having trouble using the raft with my hurt leg.  The rays are common in the shallows just west of here.  Take the bombs and use my raft to bring me back their stingers!\n\nOh yeah, watch out for the hammerheads!", sourceObjective = "Use the Goblin Fishing Bombs to kill 3 Sting Rays and bring back their stingers to Fiznix. The Rays can be found in the shallows west of Anglers Wharf.", progress = "Find any sting rays in the shallows?", completion = "Looks like you're pretty handy with those bombs!", sourceObjectiveStatus = "unverified-source-field" }
quests[30680] = { id = 30680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Oh thank you, thank you, thank you. If you hadn't come along...\n\nWait! There must be other survivors in the Nook like me!\n\nPlease, {class}, I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.", sourceObjective = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30681] = { id = 30681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Oh, thank you! There's no way I could have made it back on my own.\n\nCome to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?", sourceObjective = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30682] = { id = 30682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "I can't believe you made it here!\n\nI don't know how much longer I could have stayed hidden in here.\n\nI'm sure that there are others. {class}, we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!", sourceObjective = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", progress = "There are survivors out there? Surely there are more, {name}?", completion = "We didn't know that there were any survivors out there.\n\nThank you for bringing them to safety, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30683] = { id = 30683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Traveler's Misfortune", description = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?!\n\nNow we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's!\n\nYou threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.", sourceObjective = "Search the Abandoned Wreckage for supplies.", progress = "Nephew Bentnail has already eaten two days worth of food. I hope you found us more!", completion = "You were attacked by a mogu? That sounds terrible!\n\nI hate to ask, but did you manage to pick up any supplies while you were fighting for your life?\n\nNo?! This is very bad luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[30684] = { id = 30684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only <his/her> thoughts. <He/She> will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", sourceObjective = "Brave the path of Seeker's Folly to find Lorewalker Cho, stopping to reflect at the three shrines along the way.", progress = "There are two shrines on the path below us, and one more just behind us.", completion = "Ah, you made it, and you honored the shrines.\n\nI knew you could handle it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30690] = { id = 30690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unmasking the Yaungol", description = "Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury.\n\nYou will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you.\n\nDefeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.", sourceObjective = "Lure Kobai into the Blinding Rage Trap, steal the Mask of Malevolent Fury from him, and then defeat Malevolent Fury.", progress = "Is Malevolent Fury gone?", completion = "I should feel shame at the loss of the village. I should feel great pride in your success. \n\nI should feel many things, but must not allow myself to. Until our struggle with the sha is complete, we must maintain total control of our emotions.", sourceObjectiveStatus = "unverified-source-field" }
quests[30691] = { id = 30691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misery", description = "While you are in the water below, you should slay Nahassa, the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon.\n\nFind his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.", sourceObjective = "Put Nahassa out his misery.", progress = "Please, {name}. Even the great beasts of this world have a right to die in dignity.", completion = "Nahassa's fevered suffering has come to an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[30692] = { id = 30692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Trail: To Kota Basecamp", description = "This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine.\n\nGo, protect the next wave of grummles on their trek to Kota Basecamp.\n\nIf at least one survives, good fortune will find its way to you.", sourceObjective = "Protect a group of grummles from the Burlap Waystation to the Kota Basecamp. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trial or return to the Burlap Waystation and wait for the next group to leave.", progress = "Welcome to Kota Basecamp, friend of grummles.", completion = "Ha ha! Hero of grummles! Welcome to Kota Basecamp. Enjoy good fortune for most happy grummle delivery.", sourceObjectiveStatus = "unverified-source-field" }
quests[30694] = { id = 30694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tread Lightly", description = "My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes.\n\nAs the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\"\n\n<Koro hands you a long tree branch.>\n\nHere, this is scrutiny.\n\nIt should be long enough to set the traps off at a safe distance.", sourceObjective = "Use \"Scrutiny\" to set off 10 Riverblade Spike Traps from a safe distance.", progress = "Well, I don't see any spikes in your face. That's a good sign.", completion = "Every trap you sprang is a life saved, be it pandaren, beast, or otherwise. Nobody deserves an honorless death like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[30695] = { id = 30695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahead on the Way", description = "Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues.\n\n\"She who mends torn umbrella will be more dry than she who strikes at rain.\"\n\nWhile I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case.\n\nTake out those maws of despair and give my order a chance at reclaiming the temple grounds.", sourceObjective = "Kill the Maw of Despair in both the eastern and western pagodas at the Temple of the Red Crane.", progress = "Koro said there's a pagoda on either side of the temple. Let's find them and wipe out the sha presence in both.", completion = "Koro's metaphors can get a little tiring, but there's always true wisdom behind them.", sourceObjectiveStatus = "unverified-source-field" }
quests[30698] = { id = 30698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenger Hunt", description = "YOU!  You're just who I have been looking for!\n\nI need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself.\n\nYou see those shipwrecks nearby?  I bet they have just what I need if you can get to it and fish it out.  Take my fishing raft and see what you can find!  My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.", sourceObjective = "Use the Goblin Fishing Raft to fish up 15 Rusty Shipwreck Parts out of the floating debris near the shipwrecks.", progress = "Did you find the shipwrecks?", completion = "Looks like you found plenty of parts, another set of fishing bombs coming right up!  Thanks {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30699] = { id = 30699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Winter's Blossom", description = "The battle against the Sha is eternal - we can not leave this place. \n\nBut I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. \n\nYou have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.", sourceObjective = "Speak with Lin Silentstrike at Winter's Blossom in Kun-Lai Summit.", completion = "Shado-Master Chong sent you, hmm?\n\nYes, we received his request for reinforcements.\n\nWe are in no position to grant it, however. We've just concluded a battle of our own, and the monastery's been locked up tight. \n\nWe can't even get reinforcements here, and we're just down the hill!", sourceObjectiveStatus = "unverified-source-field" }
quests[30700] = { id = 30700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapclaw", description = "A giant, poisonous crab is wrecking havoc on our local abalone stores.  I need you to go down into narsong trench and take it out!", sourceObjective = "Kill Snapclaw in a cave at the bottom of Narsong Trench and return with his claw as proof.", progress = "Did you take out that nasty crawler?", completion = "That is quite the claw, Snapclaw must be bigger than I thought!  No matter, job well done {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30701] = { id = 30701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viseclaw Soup", description = "Nothing tastes quite like viseclaw soup.  It's a krasarang specialty!\n\nI was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes!\n\nI need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!", sourceObjective = "Kill Viseclaw Fishers on the beach and return with 16 eyes to make some yummy soup.", progress = "How many of their beady little eyes did you get?", completion = "Thanks {class}, this might be my best batch of soup yet!", sourceObjectiveStatus = "unverified-source-field" }
quests[30704] = { id = 30704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen in the Mist" }
quests[30705] = { id = 30705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Log" }
quests[30706] = { id = 30706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angry Scribblings" }
quests[30710] = { id = 30710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Trolls", description = "We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all.\n\nMy husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so.\n\nWe will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.", sourceObjective = "Kill 10 Zandalari Stalkers and 5 Zandalari Hexers", sourceObjectiveStatus = "unverified-source-field" }
quests[30714] = { id = 30714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Leaders", description = "And, now they fear you.\n\nTheir leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them.\nMake them hurt. For us.", sourceObjective = "Kill the Zandalari Blademaster and Zandalari Mage", sourceObjectiveStatus = "unverified-source-field" }
quests[30715] = { id = 30715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line Unbroken", description = "When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. \n\nIf you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate.\n\nAnd try to keep the birds off them.", sourceObjective = "Lay Shado-Master Zhiyao, Liu of the Thousand Blows and Shiya Boldblade to rest.", progress = "Our comrades, are they at rest?", completion = "Good. I will see to it that the armor is returned to their pupils.", sourceObjectiveStatus = "unverified-source-field" }
quests[30716] = { id = 30716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Hope", description = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us.\n\nProve your dexterity in the eyes of Chi-Ji, {name}. Find and catch the spirits of the crane.", sourceObjective = "Touch 3 Spirits of the Crane.", progress = "Return when you are finished, {name}. Now go!", completion = "Chi-Ji smiles on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30717] = { id = 30717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifts of the Great Crane", description = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate.\n\nWe use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.", sourceObjective = "Obtain 10 Gifts of the Great Crane.", progress = "Even the smallest, flimsiest feather is proof enough that Chi-Ji loves us.", completion = "Thank you, {name}.\n\nReturn to us again soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[30718] = { id = 30718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students of Chi-Ji", description = "Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji.\n\nProve yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.", sourceObjective = "Duel 10 Students of Chi-Ji.", completion = "With every battle - a win or a loss - you improve. You become faster, hardier, cleverer... better.", sourceObjectiveStatus = "unverified-source-field" }
quests[30723] = { id = 30723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor, Even in Death", description = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us.\n\nThe yaungol are our enemies.\n\nStill, we must prove we are better than they. We will show them honor in death.\n\nAs after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.", sourceObjective = "Kill 12 Kun-Lai Scavengers.", progress = "Killing those birds may not soothe my anger, but at least it proves that we are better than our enemies. They would not do such a thing.", completion = "Good. After what they have done, I would not show the Yaungol kindness in life. But neither will I allow their bodies to be eaten by the birds.", sourceObjectiveStatus = "unverified-source-field" }
quests[30724] = { id = 30724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Wall!", description = "They are attacking again!\n\n<Lin looks to the Ox Gate.>\n\nArchers... on the wall!\n\nI need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption...\n\nIt matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.", sourceObjective = "Speak to Kite Master Len at Winter's Blossom in Kun-Lai Summit to take a kite up to the Ox Gate. Once there, speak to Suna Silentstrike.", progress = "Lin sent you for me? How sweet.", completion = "Wow, that was quite a bit of kite-flying there. Good job getting up here and not dying.\n\nIt's good you're here, too. Lao-chen's got an idea he's working on, but in the meantime we've got yaungol to deal with.", sourceObjectiveStatus = "unverified-source-field" }
quests[30725] = { id = 30725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane", description = "We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, {name}.\n\nHer name is Ellia Ravenmane. This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.", sourceObjective = "Defeat Ellia Ravenmane at the Angkhal Pavilion.", progress = "Yes, you and Ellia should be a perfect match...", completion = "Very good!\n\nThe next time you return, you will face a new challenger. Continue winning, and your favor in the eyes of Chi-Ji will increase.", sourceObjectiveStatus = "unverified-source-field" }
quests[30726] = { id = 30726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minh Do-Tan", description = "Your next challenger is another relatively new trainee. His name is Minh Do-Tan, and he has won his last two matches.\n\nHe will be waiting for you near the crane statue to the south.", sourceObjective = "Defeat Minh Do-Tan.", progress = "Fight hard, {name}.", completion = "Well done, {name}. You are beginning to make a name for yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[30727] = { id = 30727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Rematch", description = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\".\n\nWe discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.", sourceObjective = "Defeat Ellia Ravenmane near the base of the Pedestal of Hope.", completion = "Twice fought, twice defeated. It stands to reason that Ellia will not be requesting more rematches anytime soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[30728] = { id = 30728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Long-Fat", description = "You have been matched with a... special trainee. His name is Fat Long-Fat.\n\n<Thelonius chooses his words carefully.>\n\nFat Long-Fat... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you.\n\nYou will find him atop Angkhal Pavilion.", sourceObjective = "Defeat Fat Long-Fat at the top of Angkhal Pavilion.", completion = "Of course you won. Fat Long-Fat does not fight to win. He fights for... other reasons.\n\nI fear I've spoken too much about this subject already. From now on... no more questions about Fat Long-Fat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30729] = { id = 30729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia Bates", description = "We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates.\n\nShe is your next challenger. You will find her on the island's western shore.", sourceObjective = "Defeat Julia Bates.", progress = "Stay strong, {name}.", completion = "Another fight handily won. I anxiously await your next match, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30730] = { id = 30730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dextrous Izissha", description = "Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha.\n\nIzissha is your next challenger. He waits for you on the island's southwestern shore.", sourceObjective = "Defeat Dextrous Izissha.", completion = "Excellent work, {name}! You continue to gain favor in the eyes of Chi-Ji.\n\nYour next battle will be one to remember. You will not be fighting a trainee. Instead, you will face one of your trainers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30731] = { id = 30731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuo-Na Quillpaw", description = "Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer.\n\nToday, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.", sourceObjective = "Defeat Kuo-Na Quillpaw.", completion = "You continue to impress, {name}.\n\nCome again soon. Your training is not over yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30732] = { id = 30732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Revenge", description = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle.\n\n\"I will destroy {name},\" she said.\n\nI have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.", sourceObjective = "Defeat Ellia Ravenmane at Dome Balrissa.", completion = "I will consult directly with Chi-Ji about Ellia's behavior. She treads on thin ice.", sourceObjectiveStatus = "unverified-source-field" }
quests[30733] = { id = 30733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tukka-Tuk", description = "You are making a name for yourself, {name}. I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem.\n\nHis name is Tukka-Tuk, the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.", sourceObjective = "Defeat Tukka-Tuk.", completion = "Well done, as usual.\n\nI trust I will see you again soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[30734] = { id = 30734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huck Wheelbarrow", description = "Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever.\n\nHuck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.", sourceObjective = "Defeat Huck Wheelbarrow.", completion = "There remains only one trainee ranked higher than you.\n\nI have a feeling that you will be facing him when you return.", sourceObjectiveStatus = "unverified-source-field" }
quests[30735] = { id = 30735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mindel Sunspeaker", description = "Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane.\n\nYour challenger's name is Mindel Sunspeaker, and he awaits you within Angkhal Pavilion.", sourceObjective = "Defeat Mindel Sunspeaker.", completion = "You are now our highest-ranked trainee. You are no longer obligated to participate in trainee duels. Congratulations!\n\nOf course, there are still other ways to prove yourself. I have the feeling I will be seeing you again...", sourceObjectiveStatus = "unverified-source-field" }
quests[30736] = { id = 30736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yan Quillpaw", description = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan.\n\nHe will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.", sourceObjective = "Defeat Yan Quillpaw at the Pedestal of Hope.", completion = "And with that victory, I suppose we've run out of challengers for you to fight! Other than me, of course.\n\nBut... I don't fight. I mean, you wouldn't want to fight me. It would... not go well for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30737] = { id = 30737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Long-Fat: Rematch", description = "Fat Long-Fat has requested another match with you. I find this strange. And concerning.\n\nHe will be waiting atop the Dome Belrissa.", sourceObjective = "Defeat Fat Long-Fat atop Dome Belrissa.", completion = "I believe I understand why he wanted to fight you a second time, though I need to speak with Chi-Ji before I can be sure.\n\nCome back soon, {name}. I think it is time you learned the true nature of Fat Long-Fat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30738] = { id = 30738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelonius", description = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth.\n\nI will meet you on the western shore, and we will duel.", sourceObjective = "Defeat Thelonius.", completion = "You are truly worthy of the secret of Fat Long-Fat. Here it is:\n\nFat Long-Fat and Chi-Ji are one and the same. Fat Long-Fat is the Red Crane.\n\nHe believes that the Cradle is in great danger.\n\nHe believes there is one person that can save it.\n\nHe believes that you are that person, {name}.\n\nStay in touch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30739] = { id = 30739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Redemption", description = "Ellia Ravenmane, your rival, has returned. She demands that you meet her atop the Pedestal of Hope.\n\nYou need to understand, {name}... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal.\n\nGood luck, {name}.", sourceObjective = "Defeat Ellia Ravenmane atop the Pedestal of Hope.", completion = "The Cradle of Chi-Ji has long been a bastion of hope; a place free of despair. Ellia Ravenmane tried to plant the seeds of despair on our island... and you stopped her.\n\nWe owe you a debt of gratitude, {name}. You are welcome to return whenever you like.", sourceObjectiveStatus = "unverified-source-field" }
quests[30740] = { id = 30740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of Chi-Ji", description = "While you will always hold a place of honor among our order, you are still welcome to participate in our duels.\n\nOne of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.", sourceObjective = "Defeat a Champion of Chi-Ji.", completion = "Done masterfully, as always.\n\nWe hope to see you again soon, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30742] = { id = 30742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut it Down", description = "I mussed up. Bad.\n\nIt's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so.\n\nI fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", sourceObjective = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", progress = "I shoulda never fed them goots.", completion = "Thank you, friend. Let this be a lesson to you: never feed the goots.", sourceObjectiveStatus = "unverified-source-field" }
quests[30743] = { id = 30743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet Kafa", description = "It was genius: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET.\n\nBut its over now. Uncle is upset and peak is a muss. All thats left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.", sourceObjective = "Mark 10 Kafa'goot \"Deposits\" on Kota Peak.", completion = "Great, I'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea.", sourceObjectiveStatus = "unverified-source-field" }
quests[30744] = { id = 30744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nI pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", sourceObjective = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", sourceObjectiveStatus = "unverified-source-field" }
quests[30745] = { id = 30745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen they ate the goots full of kafa...\n\n<Keenbean shoots Gootfur a mean glance.>\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", sourceObjective = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", completion = "You made it!\n\nYeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You brave. Or lucky. Or dumb.\n\nMaybe all three.", sourceObjectiveStatus = "unverified-source-field" }
quests[30746] = { id = 30746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fair Trade", description = "<The roar bellows out again, louder and more fierce than any of the yetis you've encountered so far. Again, a grummle voice replies...>\n\nEep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!\n\n<The beast called Kota Kon answers with another meaty roar.>", sourceObjective = "Bring the Bundle of Kafa'kota Berries to the Lair of Kota Kon, near the top of Kota Peak.", progress = "Kota Kon wants more kafa, but I already fed her all I have! Then I tried giving her a nice bow, but she's not satisfied!\n\n<The terrified grummle gulps and leans in close to whisper.>\n\nI think she can smell the kafa I drank for breakfast...", completion = "You brought kafa?!\n\nYou...\n\nMagnificent...\n\nLuckydo...\n\nHurry, let's give it to her! Maybe she won't have us both for snack...", sourceObjectiveStatus = "unverified-source-field" }
quests[30747] = { id = 30747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Grind", description = "Okayyy... well, she's not eating anybody. That's a good start.\n\nShe must want more kafa, but we gotta give her somethin' to do with all the extra energy...\n\nI got it! The Burlap Trail! She can smash hozen out there all day!\n\n<Burrberry turns to the massive beast.>\n\nWhat do you think, pretty girl? Wanna smash hozens?!\n\nI think so. Here, feed her my emergency flask of kafa. She likes you.", sourceObjective = "Feed the Flask of Kafa to Kota Kon at Kota Basecamp, then kill 100 Hozen along The Burlap Trail.", progress = "Don't push our luck... we promised her hozens-smashies.", completion = "Wow! That was VIOLENT.\n\nNot sure what I was expecting...\n\nThanks to you, I think we may have just formed a mutually beneficial relationship with the Terror of Kota Peak.", sourceObjectiveStatus = "unverified-source-field" }
quests[30750] = { id = 30750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off the Wall!", description = "The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers.\n\nThe good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall.\n\nYou'll find the archers just out that door.", sourceObjective = "Kill 12 Osul Veteran Archers or Osul Fire-Warriors.", completion = "Ha! I could see them flying. Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30751] = { id = 30751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Terrible Sacrifice", description = "I have an idea, and... am prepared to make a terrible sacrifice.\n\nAs much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate...\n\nIt is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.", sourceObjective = "Gather 6 Barrels of Yaungol Fire Oil.", progress = "Do you have the oil?", completion = "Alright. I am off to prepare our next move. Good luck, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30752] = { id = 30752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbelievable!", description = "I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation.\n\nFriend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.", sourceObjective = "Speak to the Shado-Pan Monastery Sentinel to gain entrance to the Shado-Pan Monastery.", progress = "Unbelievable!", completion = "No... this is worse than I could have possibly imagined. The monastery itself has been compromised...", sourceObjectiveStatus = "unverified-source-field" }
quests[30753] = { id = 30753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jumping the Shark", description = "There is only one way to kill sharks where I come from, with your bare hands!\n\nI dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time.  Hop on the first one you see and take it out!", sourceObjective = "Kill a frenzied reef shark with your bare hands.", progress = "Did you show that shark who's boss?", completion = "That was a huge shark you took out {name}!  Color me impressed!", sourceObjectiveStatus = "unverified-source-field" }
quests[30754] = { id = 30754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bright Bait", description = "Certain fish are only attracted to bright lights.  The forest north of here is home to a local pandaren firefly called a suncrawler.\n\nYou should be able to find them on the base of the tree trunks all around that area.  Bring me back a handful of them and I can use them for bait!", sourceObjective = "Collect 7 Suncrawlers in the forest north of Anglers Wharf.", progress = "Any luck with those suncrawlers?", completion = "These should do nicely {name}.  Thanks for the help!", sourceObjectiveStatus = "unverified-source-field" }
quests[30757] = { id = 30757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord of the Shado-Pan", description = "Our lord, Taran Zhu, has been overcome by a sha of pure hatred. The whole monastery has been lost!\n\n{class}, you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.", sourceObjective = "Rid Taran Zhu of his possession by the Sha of Hatred.", completion = "Thank you, {class}. I am cleansed of all hatred.\n\nKnow that you are a hero of the Shado-Pan.", sourceObjectiveStatus = "unverified-source-field" }
quests[30759] = { id = 30759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mouth of Hatred", description = "We've lost the Shado-Pan Monastery!\n\nInitiate Kia was able to get word to me that the sha have possessed everyone inside. Most troubling, that includes our lord, Taran Zhu.\n\n{class}, will you head north up into the mountains? Enter the monastery through the Cloudstrike Dojo. Kia is still hiding inside.", sourceObjective = "Speak with Initiate Kia at the Cloudstrike Dojo inside the Shado-Pan Monastery.", sourceObjectiveStatus = "unverified-source-field" }
quests[30763] = { id = 30763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piranha!", description = "Certain fish are very difficult to catch.  The wolf piranha falls squarely into this category.\n\nLucky for me that you showed up!  Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.", sourceObjective = "Fish up 5 Wolf Piranha from the Krasarang River in Krasarang Wilds.", progress = "Any luck?", completion = "I see you still have all your fingers, nice work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30765] = { id = 30765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regaining Honor", description = "{name}, the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner.\n\nYou have to kill Humongous and regain Zhen's honor! If you don't, I will.", sourceObjective = "Retrieve Zhen's Banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30766] = { id = 30766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profiting off of the Past", description = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>", sourceObjective = "Collect 11 more Mogu Relics.", sourceObjectiveStatus = "unverified-source-field" }
quests[30767] = { id = 30767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risking It All", description = "Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. \n\nI know we don't have much time, but we need to think of another way...", sourceObjective = "Remove the thorn from Shen-zin Su.", completion = "The first step is done, but now we must save Shen-zin Su!", sourceObjectiveStatus = "unverified-source-field" }
quests[30768] = { id = 30768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Husband...", description = "Lin...\n\nI don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up.\n\nOnce Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.", sourceObjective = "Meet up with Suna Silentstrike at Longying Outpost in the Townlong Steppes.", completion = "Good. Looks like the rest of the Shado-Pan decided it was a good time to catch up.", sourceObjectiveStatus = "unverified-source-field" }
quests[30769] = { id = 30769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Assault", description = "Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow.\n\nGo and confront the Osul Sharphorn up the mesa to the west.\n\nLet them know that we are here, and that we are not scared of their threats.", sourceObjective = "Kill 6 Osul Sharphorns.", completion = "Well done, {name}. I hope you showed those cretins no mercy.", sourceObjectiveStatus = "unverified-source-field" }
quests[30770] = { id = 30770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Rampant", description = "There is one thing that every army needs, and that is a supply line.\n\nThe enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food.\n\nLuckily for us, the yaks and mushan beasts of this region are easily scared.\n\nSneak in, give the beasts a good slap, and watch the results.", sourceObjective = "Scare 8 Long-Haired Yaks or Steppebeasts.", completion = "Ohohoho! I saw those animals trailing dust from up here.\n\nThose yaungol are probably still wondering what happened.", sourceObjectiveStatus = "unverified-source-field" }
quests[30771] = { id = 30771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Pitch", description = "When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch.\n\nThey use this terrible weapon to shed not only blood, but to raze the homes of their enemies.\n\nI need you to collect some of this pitch while you are in their camp.\n\nWe will use it to show the yaungol that when you play with fire, you can get burned.", sourceObjective = "Collect 8 Dark Pitch.", progress = "The yaungol are not content merely to defeat their enemies. No, they would rather destroy and decimate them.", completion = "It still smells fresh.\n\nGood job, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30772] = { id = 30772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Red", description = "Ahead of us is the main thrust of the yaungol army.\n\nHere, they prepare their vast army to attack the villages of Kun-Lai.\n\nIf we strike at the Osul now, we can cut them at their very core.\n\nRemember, for every of their number that we strike down here, we save one of our own back at home.", sourceObjective = "Kill 8 Osul Marauders or Osul Spitfires.", completion = "That should put a serious dent in their numbers.\n\nI doubt they will be able to recover from such losses.", sourceObjectiveStatus = "unverified-source-field" }
quests[30773] = { id = 30773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitching In", description = "The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit.\n\nThose terrible weapons must be destroyed.\n\nTake these explosives. I've covered them in the pitch that you collected.\n\nToss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.", sourceObjective = "Use Ban's Explosives to destroy 6 Osul Ballistas.", progress = "Fire is a cruel weapon. Luckily, we are only using it to destroy weapons of war.", completion = "Good, {class}.\n\nNow that they cannot hide behind their siege weapons, they have no choice but to face us.", sourceObjectiveStatus = "unverified-source-field" }
quests[30774] = { id = 30774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranger Rescue", description = "I must ask a most important task of you, {name}.\n\nSomewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world.\n\nPlease find him and return him to me, and save as many of our fellow Shado-Pan as you can as well.\n\nYou should find keys to those cages on the Osul Marauders.", sourceObjective = "Unlock Drywood Cages to save 4 Longying Rangers and Lin Silentstrike.", completion = "I am truly sorry to hear that Lin did not make it.\n\nSuna is taking the news quite hard. She will forgive me in time.\n\nAs for the rest of the Shado-Pan that you saved, well, I am very grateful to see them returned safe and sound.", sourceObjectiveStatus = "unverified-source-field" }
quests[30775] = { id = 30775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exile", description = "What is there to say, stranger?\n\nI fought Jung Duk and lost. I was the fool to believe he would fight fairly.\n\nNow, my own brothers turned against me, and here I am, speaking to our enemies.\n\nI know you have come for Osul blood.\n\nI only ask that you hunt down the three who betrayed me.\n\nUrang, who poisoned my drink. Ku-Tong, who bent my spear. And Battat, whose dagger slipped into my side as my victory was assured.\n\nDo this, and I can die in peace.", sourceObjective = "Kill Urang, Ku-Tong, and Battat.", progress = "How could they have betrayed me? They were once my brothers!\n\nWhy did they turn on me? WHY?\n\nI hate them! I will slaughter them all!", completion = "It pleases me to know those cowards died at your hands.\n\nPerhaps now, this burning tide in my heart will ebb.", sourceObjectiveStatus = "unverified-source-field" }
quests[30776] = { id = 30776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jung Duk", description = "THIS. IS. WAR.\n\nI will have the heads of everyone who took Lin from me. EVERYONE!\n\nWe will begin with the Osul leader, Jung Duk.\n\nTake this Shado-Pan war banner and place it at the center of their camp.\n\nJung Duk will have no choice but to face you.\n\nShow him no mercy, {name}.", sourceObjective = "Plant the Shado-Pan Banner on the Ceremonial Pile, then kill Jung Duk.", progress = "Jung Duk's legacy is written in the blood of innocents.", completion = "Jung Duk is dead at last.\n\nHundreds, perhaps thousands, lost their lives due to his violent aggression.\n\nThough they are not here to witness his demise, they owe deep gratitude to your bravery today.", sourceObjectiveStatus = "unverified-source-field" }
quests[30777] = { id = 30777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Suna", description = "I have bad news. When I returned, Suna was already gone.\n\nThe others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression.\n\nI cannot allow her to venture into dangerous territory alone.\n\nI've already prepared a group of soldiers to push further east.\n\nWe are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.", sourceObjective = "Speak to Ban Bearheart after arriving at Hatred's Vice.", completion = "Well, we made it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30778] = { id = 30778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust to Dust", description = "If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot.\n\nTake this torch and set fire to the villagers' corpses.\n\nThe incense from the torch should purify the earth and air around them as well.\n\nEven our enemies deserve to be laid to rest.", sourceObjective = "Use the Shado-Pan Torch on 20 Palewind Villagers.", progress = "The stench of death is overpowering.", completion = "Good work, {name}.\n\nHopefully, their spirits are in a better place.", sourceObjectiveStatus = "unverified-source-field" }
quests[30779] = { id = 30779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaying the Scavengers", description = "The rotting corpses are attracting hyena scavengers.\n\nIn addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight.\n\nGo and eradicate the beasts. It is unfortunate, but ultimately for the best.", sourceObjective = "Kill 8 Ashfang Hyenas.", progress = "It is better to be safe than sorry.", completion = "Thank you, {name}. It was an unpleasant task, but it had to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[30780] = { id = 30780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemic Research", description = "As we entered the village, I couldn't help but notice yaungol totems lying around this camp.\n\nI have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out.\n\nCould you bring me some of these totems for further inspection? I would like to study them.", sourceObjective = "Collect 9 Palewind Totems.", progress = "I do believe the totems could be of use to us.", completion = "I was right! These totems were once used to store and conduct immense magical energies.\n\nI do believe I can use them once again to do the same.", sourceObjectiveStatus = "unverified-source-field" }
quests[30781] = { id = 30781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Toll of the Yaungol", description = "Ban has asked me to explore the village to determine what happened here.\n\nI noticed smoke rising up from the east, the west, northwest, and the south.\n\nI need someone I trust to watch my back.\n\nWhat do you say? Want to help me on my first scouting mission?", sourceObjective = "Take Xiao Tu to the smoke trails at Hatred's Vice.", progress = "Something terrible must have happened here.", completion = "Thank you for your help, {name}.\n\nWe cannot know exactly what happened here, but it's clear that something caused the yaungol to turn on one another.\n\nWhat kind of power could do this?", sourceObjectiveStatus = "unverified-source-field" }
quests[30782] = { id = 30782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Spirits", description = "The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits.\n\n{name}, if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.", sourceObjective = "Kill 10 Spiteful Spirits.", progress = "The air is thick with their malicious intent.", completion = "Well done. We cannot bring them retribution, but at least we can end their rage.", sourceObjectiveStatus = "unverified-source-field" }
quests[30783] = { id = 30783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Becomes Us", description = "I should have suspected a sha presence earlier!\n\nWe are safe as long as we stand inside the Totem of Harmony's protective wards, but many of our people were not so lucky.\n\nThey were trapped outside the camp when the sha's powers manifested, and now they turn upon each other!\n\nTake one of my totems with you. Place the totem near a crazed ally to purify them, but beware.\n\nYou may have to face the darkness that gripped them.", sourceObjective = "Use the Totem of Harmony to exorcise sha spirits from 8 Crazed Shado-Pan Rangers. Defeat the Seething Hatreds to purify your allies.", progress = "Our people are possessed by hatred. We must help them come to their senses!", completion = "Thank you.\n\nThe sha preys upon the weak and the vulnerable.\n\nIf we are not vigilant, even the strongest of us can succumb to the sha's dark influence.", sourceObjectiveStatus = "unverified-source-field" }
quests[30784] = { id = 30784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Point of No Return", description = "One of our rangers reported seeing Suna up the hill to the northwest.\n\nI am relieved to find her safe. I had feared what she would do in her grief.\n\nWould you go speak to her on my behalf?\n\nTake this totem with you. If you encounter any danger along the way, you may find it useful.", sourceObjective = "Find Suna Silentstrike.", progress = "If I could change the past, I would. If I could take Lin's place, I would.\n\nIn a thousand lifetimes, I will never be able to repay Suna's loss, or share even a measure of her grief.", completion = "What? She was possessed by the Sha of Hatred?\n\nNo. NO!\n\nDespite our differences, she was one of us. Today, the Shado-Pan has lost a dear sister.\n\nHer death will not be in vain. I will not rest until I have defeated the Sha of Hatred!\n\nSuna, I swear this to you!", sourceObjectiveStatus = "unverified-source-field" }
quests[30785] = { id = 30785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gao-Ran Battlefront", description = "With your help, we have quelled the spirits of this place.\n\nAt last, they may rest in peace.\n\nOur journey into this cursed land, I am afraid, has only begun.\n\nI have some important matters to finish up here, but we will be moving out soon.\n\nI need someone to go ahead and tell Lord Taran Zhu that we are joining him.\n\nFind him at the Gao-Ran Battlefront. Tell him what has transpired here.", sourceObjective = "Speak to Lord Taran Zhu at the Gao-Ran Battlefront in the Townlong Steppes.", completion = "Did the northern expedition go well, then? What news do you have to report?", sourceObjectiveStatus = "unverified-source-field" }
quests[30786] = { id = 30786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spear Through My Side, A Chain Through My Soul", description = "My fate is sealed. The yaungol put this spear in my side. The wound will kill me.\n\nThe yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound.\n\nMy death, I cannot stop. My imprisonment... you may be able to help me with this.", sourceObjective = "Slay Dmong Naruuk, the shaman who holds Orbiss hostage.", progress = "I will not die before having my revenge.", completion = "I am freed.\n\nThe yaungol must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[30787] = { id = 30787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Torches", description = "Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will.\n\nIf we refuse, they kill us. Even if we oblige... they kill us.\n\nThe yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.", sourceObjective = "Obtain 6 Mist-Shaman's Torches.", progress = "I can use these torches in my revenge.\n\nI have not succumbed to this wound yet. I can still have my revenge before I die.\n\nThere is time yet.", completion = "This torch... the yaungol once used these to communicate with me, with my people.\n\nNow, they use them to undo us.", sourceObjectiveStatus = "unverified-source-field" }
quests[30788] = { id = 30788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss", description = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength.\n\nOne of my kind is also known for his strength. His name is Golgoss.\n\nGolgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.", sourceObjective = "Summon Golgoss by planting the Mist-Shaman's Torches into the Peat Clump in the Upper Sumprushes.", completion = "Golgoss does not speak your language, other than a few words. I suppose I am unique in this regard.\n\nHe thanks you for summoning him.", sourceObjectiveStatus = "unverified-source-field" }
quests[30789] = { id = 30789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss", description = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss' ferocity is second to none.\n\nHe rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.", sourceObjective = "Summon Arconiss by planting the Mist-Shaman's Torches into the Peat Mound in the Upper Sumprushes.", progress = "Arconiss' size belies his prowess in battle. He will be an asset.", completion = "It will be difficult to lose with Arconiss by my side.", sourceObjectiveStatus = "unverified-source-field" }
quests[30790] = { id = 30790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss Hungers", description = "Golgoss' strength is great, but he requires nutrition before he can use it.\n\nThe snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.", sourceObjective = "Obtain 10 Snarlvines.", progress = "Golgoss' hunger is great.", completion = "We are one step closer to my goal.", sourceObjectiveStatus = "unverified-source-field" }
quests[30791] = { id = 30791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss Thirsts", description = "Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened.\n\nThe rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.", sourceObjective = "Obtain 4 Clotted Rodent's Blood.", progress = "Our preparation will not take much longer.", completion = "Yet another step closer to completing my mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[30792] = { id = 30792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orbiss Fades", description = "I knew death would come. I did not know that it would come this fast.\n\nI must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind.\n\nGather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.", sourceObjective = "Obtain 8 Gushing Mists by walking through mist geysers in the Upper Sumprushes.", completion = "I told you earlier, this wound would be my death. While you have bought me a bit more time, it is not long now.", sourceObjectiveStatus = "unverified-source-field" }
quests[30793] = { id = 30793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists' Opportunity", description = "Now is the time to strike.\n\nGolgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle.\n\nToday, we restore the pride of our people.", sourceObjective = "Slay Jahesh of Osul.", completion = "My name will be forgotten, but my actions will not.\n\nNor will yours, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30794] = { id = 30794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Care", description = "I... am alive... but barely. They killed the rest. My friends... and family...\n\nI must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.", sourceObjective = "Heal Sage Liao to get him back on his feet.", completion = "Thank you. I suppose... I'll need to ask you to do a bit more before I can return to the village. I cannot leave the bodies of my friends and family here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30795] = { id = 30795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staying Connected", description = "The Tongue of Ba-Shon should allow us to communicate from long distances, {name}.\n\nIf the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors.\n\nMishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!", sourceObjective = "Use the Tongue of Ba-Shon in the Valley of Emperors.", completion = "Very good! The relic works!\n\nIt appears there is more going on in the Valley of Emperors than I had anticipated. It is crucial we figure out why the Mogu are opening the tombs.", sourceObjectiveStatus = "unverified-source-field" }
quests[30796] = { id = 30796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to Everything", description = "These spirits must have been released when the tombs were opened... \n\nDeath was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next.\n\nYears of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.", sourceObjective = "Destroy 5 Tormented Spirits.", progress = "Have you disposed of the spirits yet?", completion = "You have done them a great service, {name}.\n\nIt is a cruel fate to be stuck between the living world and the afterlife.", sourceObjectiveStatus = "unverified-source-field" }
quests[30797] = { id = 30797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Was Almost Alive", description = "A ritual took place here, and from the looks of it wasn't successful.\n\nAmong the abandoned items a book lies open. The text on the pages is foreign to you.\n\nCarrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.", sourceObjective = "Tear a page from the open book to give to Lorewalker Cho.", progress = "What have you found, {name}?", completion = "This text is curious indeed, {name}...\n\nIt appears to have been written in the Meng dynasty, but some of the symbols are wrong. I don't think the Mogu wrote this, although it is oddly close.\n\nIt will take me some time to translate. Keep moving and see if you can find anything else.", sourceObjectiveStatus = "unverified-source-field" }
quests[30798] = { id = 30798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Emperor's Shield", description = "The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now.\n\nWith this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating!\n\nThe Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest.", sourceObjective = "Stop the Spiritbinding Ritual in the Tomb of Secrets.", progress = "Have you gone to the Tomb of Secrets yet?", completion = "The Mogu and the Zandalari intend to resurrect the Thunder King?!\n\nWe cannot let this happen, {name}! The Thunder King will rain destruction on this land with his return.", sourceObjectiveStatus = "unverified-source-field" }
quests[30799] = { id = 30799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tomb of Shadows", description = "Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual.\n\nMost of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there.\n\nLook for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.", sourceObjective = "Collect a rubbing of the Shen Dynasty Tablet, the Wai Dynasty Tablet, and the Qiang Dynasty Tablet in the Tomb of Shadows.", progress = "Did you find anything in the Tomb of Shadows?", completion = "These tablets recount the history of the Mogu and Zandalari alliance dating back to the time of the first Mogu emperor.\n\nBy the looks of things they have rekindled their alliance. But why now?", sourceObjectiveStatus = "unverified-source-field" }
quests[30800] = { id = 30800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Their Thunder King", description = "Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors.\n\nGetting to his remains will not be easy, {name}. The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves.\n\nOnce inside we will need to figure out where his remains have actually been placed.", sourceObjective = "Find the Bottom Fragment of Lei Shen's Tablet and restore the Tablet of Thunder.", progress = "Have you figured out where the Thunder King's remains are hidden?", completion = "We are fortunate they haven't gotten to Lei Shen's remains... yet.\n\nThe Zandalari will not give up until they have what they want.", sourceObjectiveStatus = "unverified-source-field" }
quests[30801] = { id = 30801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons from History", description = "The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery.\n\nYou must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.", sourceObjective = "Read the Tablet of Thunder in the Tomb of Conquerors.", progress = "Have you read the tablet?", completion = "They will need to move the remains to a secure location. We must go after them!", sourceObjectiveStatus = "unverified-source-field" }
quests[30802] = { id = 30802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Storm", description = "We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to ressurect him in the Valley of the Emperors. They would need to be somewhere remote and secure.\n\nIt appears that getting out of here may also prove to be a challenge....\n\nFight your way out and look for information concerning location of the remains.", sourceObjective = "Find the Blood-Revealed Map on a Zandalari Warrior.", progress = "Were you able to find any information on their location?", completion = "This is dark Zandalari blood magic. Once we're done with the map it should be burned.\n\nThe map indicates they have headed for the coast just outside of a tiny fishing village called Zouchin. The villagers there may be able to help us find the Zandalari. We just have to hope the village is still standing...", sourceObjectiveStatus = "unverified-source-field" }
quests[30804] = { id = 30804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fearmaster", description = "I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today.\n\nThem yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.", sourceObjective = "Kill the Fearmaster.", progress = "So many strangers in these lands these days. Luckily you {class} seem to be all right.", completion = "Yee haw! I knew you {race} might be good for somethin'. He must of made a very satisfying \"thump\" when he hit the ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[30805] = { id = 30805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice", description = "After the mercenaries robbed us, most left.\n\nBut one of them... after the others took all we had, he ran the rest of us through. For sport!\n\nGet justice for the fallen. Perhaps news of their death will raise my spirits enough to go on.\n\nYou'll find them just west of here.", sourceObjective = "Kill Captain Ripflesh and 6 Blackmane Mercenaries.", completion = "Ahh.. they are dead. Already, I can feel my spirits lifting. Soon I will have the strength to return to the village.", sourceObjectiveStatus = "unverified-source-field" }
quests[30806] = { id = 30806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Life", description = "Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. \n\nIt doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet.\n\nThe materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village.", sourceObjective = "Gather an Opalescent Blue Crab Shell and 8 Stolen Pandaren Spices.", progress = "Are those the ingredients for Incense of Life I smell on you? Or... perhaps you haven't bathed recently.", completion = "Beautiful, beautiful. Better to not need to bury our friends, but if we must, it is good they will have a fitting ceremony.", sourceObjectiveStatus = "unverified-source-field" }
quests[30807] = { id = 30807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Falls, For the Fallen", description = "I do not wish to dishonor my friends and leave them in unmarked graves.\n\nYet, we have never needed to bury so many at once, and I am in no condition to gather materials.\n\nPlease, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.", sourceObjective = "Gather 3 Waterfall-polished Stones.", progress = "The stones - have you brought them?", completion = "Good. Thank you. After this, I cannot imagine leaving my fellows to less than a proper burial.", sourceObjectiveStatus = "unverified-source-field" }
quests[30808] = { id = 30808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grummle's Luck", description = "The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail.\n\nThis is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble.\n\nRecover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.", sourceObjective = "Find 8 Stolen Luckydos.", progress = "A luckydo is a thing of much good fortune. Yaungol know nothing of how to use luckydos... yet.", completion = "Hurray! Our Luckydos. Many thanks and fortune to friend of grummles!", sourceObjectiveStatus = "unverified-source-field" }
quests[30814] = { id = 30814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foot in the Door", description = "<Lord Taran immediately pins you down with his steely gaze.>\n\n{class}, you bear the marks of many a past battle.\n\nGood! We need more seasoned people like you to hold back the front.\n\nWe've managed to secure a foothold here, but the yaungol are desperate to remove our presence.\n\nIf you wish to prove your worth, go down the hill and show the yaungol that we will not back down.", sourceObjective = "Kill 8 Osul Chargers.", progress = "We are slowly gaining ground.", completion = "Good. I can see that you are capable.\n\nI hope to rely on your talents for what is to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[30815] = { id = 30815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Death of Me", description = "I have resolved to remove this spear from my side.\n\nFor this, I require your assistance. Your grasping hands are stronger than mine.", sourceObjective = "Remove the spear from Orbiss.", completion = "By removing this spear, I have truly guaranteed my own death.\n\nThis does not frighten me.\n\nI would sooner die than live carrying the weapon of my enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[30816] = { id = 30816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking In", description = "When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?", sourceObjective = "Check on Sage Liao at the Zaochin Strand in Kun-Lai Summit.", completion = "Ahh... My cousin is wise to be worried... I am not well...", sourceObjectiveStatus = "unverified-source-field" }
quests[30817] = { id = 30817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing of Shen-zin Su", description = "This is what comes of such recklessness. How could he think this was even a possibility?\n\nNevermind, there's no time for that now. We need to act to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", sourceObjective = "Rescue and defend healers until Shen-zin Su's wound is healed.", sourceObjectiveStatus = "unverified-source-field" }
quests[30818] = { id = 30818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Fate", description = "{name}, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", sourceObjective = "Return to the Temple of Five Dawns. A cart is waiting near the Skyfire Crash-Site to take you there.", sourceObjectiveStatus = "unverified-source-field" }
quests[30819] = { id = 30819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Remains", description = "Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you.\n\nYou have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. \n\nIn the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.", sourceObjective = "Return to Li Hai and tell him about the funeral.", completion = "I see... it is tragic what has happened there. We will meet you at the graveyard to honor them.", sourceObjectiveStatus = "unverified-source-field" }
quests[30820] = { id = 30820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Funeral", description = "As I said, I will gather the town - we will be at the funeral. \n\nAs the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.", sourceObjective = "Attend the funeral and light the Incense of Life.", progress = "You must light the incense to honor the dead.", completion = "Good. Let us begin the funeral.", sourceObjectiveStatus = "unverified-source-field" }
quests[30821] = { id = 30821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Grind", description = "Alright, it's time to take Kota Kon out for her \"walk.\"\n\nWe brewed two fresh pots of kafa just for her and she's all fueled up!", sourceObjective = "Speak with Kota Kon at Kota Basecamp to ride her, then kill 100 Hozen along The Burlap Trail.", progress = "Kota Kon's waiting for you! She won't let anyone else ride her.", completion = "Hah hah! We could hear those monkeys screamin' from over here!\n\n<Burrberry turns to Kota Kon.>\n\nWho's a pretty girl? You are!!", sourceObjectiveStatus = "unverified-source-field" }
quests[30823] = { id = 30823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut it Down", description = "My cousin over at Kota Basecamp mussed up. He mussed up bad.\n\nHe was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so.\n\nHe fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", sourceObjective = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", completion = "Thank you for helping to correct my mistake, friend. Let this be a lesson to you: never feed the goots.", sourceObjectiveStatus = "unverified-source-field" }
quests[30824] = { id = 30824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet Kafa", description = "It was a crazy idea: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET.\n\nBut its over now. Uncle Keenbean is upset and peak is a muss. All thats left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.", sourceObjective = "Mark 10 Kafa'goot \"Deposits\" on Kota Peak.", completion = "I'd heard an adventurer was up there marking the deposits. Mussy work for someone with your skills, but I appreciate it.\n\nI'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea.", sourceObjectiveStatus = "unverified-source-field" }
quests[30825] = { id = 30825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nUncle Keenbean will pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", sourceObjective = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", sourceObjectiveStatus = "unverified-source-field" }
quests[30826] = { id = 30826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots.\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", sourceObjective = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", completion = "Ah, hello there! Tallmug sent a messenger yak over explaining that you would be helping us with our yeti problems.\n\nAnd you weren't torn to shreds! Yeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You're brave. Or lucky. Or dumb.\n\nMaybe all three.", sourceObjectiveStatus = "unverified-source-field" }
quests[30827] = { id = 30827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Beneath", description = "If my suspicions are correct, this place still reels from some lingering darkness.\n\nWhatever happened here... it could not have been the natural course of events.\n\nEven the yaungol are not so brutal as to slaughter their own kind to the point of... this.\n\nI will use the totems that you brought me to perform a cleansing ritual.\n\nI need someone to assist me in the ceremony. Let me know when you are ready.", sourceObjective = "Speak to Yalia Sagewhisper to begin the ceremony.\n\nThen, activate the Totem of Kindness, the Totem of Tranquility, and the Totem of Serenity.", progress = "I believe that we must drive the taint from this place.", completion = "We look upon the true face of hatred!\n\nNow it all makes sense. This is the work of the sha.", sourceObjectiveStatus = "unverified-source-field" }
quests[30828] = { id = 30828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Mere", description = "Pools of the same murky substance that came out of Mei emerged in the lake recently.\n\nI will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse.\n\nYou will need to deal with whatever comes out and protect me as I complete the ritual.", sourceObjective = "Point out Pools of Corruption in Inkgill Mere to Waterspeaker Gorai to let him know you are ready to defend him while he completes the cleansing ritual.", progress = "Is the lake cleansed?", completion = "The Mere... I can feel the corruption clearing. At least now, this corruption will not spread.\n\nBut, there is one more thing we must do.", sourceObjectiveStatus = "unverified-source-field" }
quests[30829] = { id = 30829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tongue of Ba-Shon", sourceObjective = "Assist Lorekeeper Cho in performing the Binding of Ba-Shon.", progress = "I'll need to bind my essence to the Tongue, then you can use it to speak with me from anywhere.", completion = "This must be a very powerful relic for Zuan to want it back so badly.\n\nIt frightens me to think of what else they may find in the tombs...", sourceObjectiveStatus = "unverified-source-field" }
quests[30834] = { id = 30834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Father and Child Reunion", description = "They survived? My father is alive!\n\nI thought we would all die here in this horrible mere, at the hands of these insane Jinyu.\n\nI will find my way back - meet me back at camp.", sourceObjective = "Return to Merchant Shi and Wu-Peng at the southeastern shore of Inkgill Mere in Kun-Lai Summit.", progress = "My boy! He is alive!", completion = "You found him! This is all I have to give, but in finding my son, you have more than earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30855] = { id = 30855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Shai Hu", description = "I can hear the voice of the Mere - it has been purified.\n\nBut, this chapter in my people's history will never be closed - not until we defeat Shai Hu.\n\nHe has retreated to the central island in the Mere, corrupting our holiest of sites.\n\nBeware - he is strong. But, after all we have done, I am confident we will be stronger.", sourceObjective = "Defeat Shai Hu. He can be found at the Waterspeaker's Sanctuary, the island in the center of Inkgill Mere in Kun-Lai Summit.", completion = "Thank you, {name}. You have assured that this corruption will not spread, and that my people - those who have not been corrupted - will be able to live on and found a new village. \n\nOur history will live on. You have done more for us than we could have ever hoped.\n\nThank you, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30879] = { id = 30879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1: Brewmaster Chani", description = "Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", sourceObjective = "Defeat Brewmaster Chani.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger.", sourceObjectiveStatus = "unverified-source-field" }
quests[30880] = { id = 30880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1: The Streetfighter", description = "Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", sourceObjective = "Defeat the Streetfighter.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger.", sourceObjectiveStatus = "unverified-source-field" }
quests[30881] = { id = 30881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2: Clever Ashyo & Ken-Ken", description = "You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side.\n\nThis will teach them the strength of friendship, and possibly entertain me in the process.\n\nGo to the north eastern arena and face this jinyu and hozen.\n\nDo not be gentle, they need to learn to work together.", sourceObjective = "Defeat Clever Ashyo and Ken-Ken.", progress = "Strength can come from an ally as much as from one's self.", completion = "Pity that those two did not learn their lesson yet. No matter. In time I am sure they will come to see wisdom.\n\nIn the meantime, congratulations on your victory.", sourceObjectiveStatus = "unverified-source-field" }
quests[30882] = { id = 30882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2: Kang Bramblestaff", description = "Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions.\n\nNo pressure, little {race}.\n\nGo to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited.", sourceObjective = "Defeat Kang Bramblestaff.", progress = "I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.", completion = "Ah. The Bramblestaff family have long held the championship generation after generation. I am sure this one will take the title sooner or later as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30883] = { id = 30883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3: The Wrestler", description = "Your next challenger is a favorite of mine. He draws strength from raw force and determination.\n\nPlus he has a mask.\n\nFace him in the western arena when you are ready, and good luck.", sourceObjective = "Defeat The Wrestler.", progress = "Sometimes strength can come from the outside.", completion = "Well fought, challenger. That was a fierce opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[30884] = { id = 30884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Battlefront", description = "This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred.\n\nTaoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses.\n\nIf my reports on you are correct, I can trust you with this, right {class}?", sourceObjective = "Meet with Taoshi at Dampsoil Burrow.", completion = "You look capable. Taran knows to send me the best. I like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[30885] = { id = 30885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3: Master Boom Boom", description = "Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\"\n\nHe proves however that found strength can be as deadly as personal strength.\n\nWhen you are ready, face this Master Boom Boom in the Western Arena.", sourceObjective = "Defeat Master Boom Boom.", progress = "Sometimes strength can come from the outside.", completion = "Well fought, challenger. That was a fierce opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[30886] = { id = 30886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Example Pandaren Race Quest" }
quests[30887] = { id = 30887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Intruders", description = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes. If we allow them north of the barricade, we may lose our foothold here.\n\nLet's clear them out. I'll be with you.", sourceObjective = "Kill 12 Krik'thik Deep-scouts with Taoshi's help.", completion = "This is where they're getting through, the eastern pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[30888] = { id = 30888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate.\n\nTake this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.", sourceObjective = "Use the Shado-Pan Flare to aid in killing 10 Krik'thik Scentlayers.", completion = "There are more getting through than I thought. I may need to stay here and clean up a while.\n\nYou've done more than your part though, {class}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30889] = { id = 30889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trap Setting", description = "Good to meet you, {class}. We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered.\n\nTaoshi said you might be able to reset some of them while you're out there. Can you help?", sourceObjective = "Rearm 8 Shado-Pan Spike Traps.", progress = "These traps have been very effective, the mantid numbers are just getting out of hand in these past weeks.", completion = "We could use a few more capable men like you around the camp. Thank you for your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30890] = { id = 30890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Watch", description = "I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts.\n\nI want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.", sourceObjective = "Deliver return orders to Scout Wei-Chin, Scout Long, Scout Ying, and Scout Jai-Gan.", progress = "This whole battlefront is being worked to the bone. We need more men out here.", completion = "Thank you. I'll have the new scouts at their posts shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[30891] = { id = 30891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treatment for the Troops", description = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting.\n\nThe mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated.\n\nI need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?", sourceObjective = "Collect 10 Violet Citron.", progress = "Mixed properly, the pollen from these flowers can eat away at the poison without doing any lasting damage to the body otherwise.", completion = "Marvelous. And in good condition too!\n\nThank you, kind {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30892] = { id = 30892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Their Feet", description = "{name}, I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison.\n\nWe need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better.\n\nPlease, {name}, get our men back on their feet so that they can get back here to safety.", sourceObjective = "Heal 8 Injured Gao-Ran Blackguards.", progress = "With the constant mantid attacks, the men are being worked to the bone. We are undermanned on all fronts.\n\nYour help means a lot to us, {name}.", completion = "There are several warriors that owe their lives to you. You have my deepest appreciation, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30893] = { id = 30893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Swarm", description = "Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.", sourceObjective = "Kill 12 Krik'thik attackers at the Gao-Ran Battlefront.", completion = "The men of the battlefront are growing to respect you. You clearly know how to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[30894] = { id = 30894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rummaging Through the Remains", description = "I do have another task for you, {name}, though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source.\n\nWhile you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.", sourceObjective = "Recover 20 Krik'thik Limbs.", progress = "I'm hoping to find a permanent counter to the mantid poison so that the men won't be afflicted in the first place. It may take some time to piece it together.", completion = "These are in great condition! Thank you, {name}!\n\nYou know, I've managed to distil some of their poison into a form that we can apply readily. I've even come up with some methods for weaving it into spell-casting, if you believe it. Would you like to give some a try?", sourceObjectiveStatus = "unverified-source-field" }
quests[30895] = { id = 30895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvised Ammunition", description = "I've got another job for you.\n\nThe dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge.\n\nThey dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of.\n\nAre you my <man/woman> for this?", sourceObjective = "Recover 16 Volatile Dread Orbs from the Ambermarsh.", progress = "Back even more quickly than expected. Did you bring the seeds?", completion = "It's good to have a {class} that I can count on.", sourceObjectiveStatus = "unverified-source-field" }
quests[30896] = { id = 30896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieves and Troublemakers", description = "I can't catch the little buggers for the life of me.\n\nKill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.", sourceObjective = "Kill 10 Agitated Nettleskins.", progress = "I haven't hated plants so much since my job back at Halfhill.", completion = "I guess you're a bit faster than me. Well, thanks.\n\nI'll try to finish collecting some orbs and get them back to camp while there's still some face to save.", sourceObjectiveStatus = "unverified-source-field" }
quests[30897] = { id = 30897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Wrong Hands", description = "Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap.\n\nI can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred.\n\nPlease, can you try to find this big sprite and get my sword back? It would mean a lot to me.", sourceObjective = "Recover Initiate Chao's Sword.", progress = "My mom warned me this was going to happen...", completion = "You... you are a lifesaver! Seriously.\n\nThank you so much!", sourceObjectiveStatus = "unverified-source-field" }
quests[30898] = { id = 30898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Swarm", description = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the cannons. Let none through.", sourceObjective = "Use a Dragon Launcher to kill 50 swarming mantid.", progress = "I can't remember the last time they swarmed this thickly. They probably haven't within my lifetime.", completion = "We're not done yet...", sourceObjectiveStatus = "unverified-source-field" }
quests[30899] = { id = 30899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Skilled Hands", description = "{name}, take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest.\n\nNurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.", sourceObjective = "Bring the Shado-Pan Crossbow Bolt Bundle to Hawkmaster Nurong.", progress = "Another wave of fliers approaches. Be ready.", completion = "There's a lot of movement on the other side of the chasm... something big is coming.", sourceObjectiveStatus = "unverified-source-field" }
quests[30900] = { id = 30900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Dread Wastes", description = "That thing is huge!\n\nThe Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.", sourceObjective = "Defeat Norvakess, the Terror of the Dread Wastes.", progress = "I've never seen anything like this...", completion = "You. You're coming with me.\n\nI've never seen someone handle themselves on the battlefield like that. I need a strong {class} like you with me when we face the Sha of Hatred.", sourceObjectiveStatus = "unverified-source-field" }
quests[30901] = { id = 30901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Southern Front", description = "I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred.\n\nI would like you to come with me.", sourceObjective = "Ride with Taran Zhu and Taoshi to Dusklight Hollow.", completion = "Let's get this taken care of so we can get down to the bridge.", sourceObjectiveStatus = "unverified-source-field" }
quests[30902] = { id = 30902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 4: Master Windfur", description = "Well done, challenger. You have reached the final round.\n\nYour last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion.\n\nFace this Master Windfur in the main arena when you are ready.\n\nAnd challenger... good luck.", sourceObjective = "Defeat Master Windfur.", progress = "The Master Windfur's strength is in the air and winds around him. He has rivaled elementals in his control of such forces.", completion = "Congratulations, champion! The day is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[30907] = { id = 30907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 4: The P.U.G.", description = "And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct?\n\nGo to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power!\n\nGood luck, Challenger!", sourceObjective = "Defeat Hackiss, Healiss and Tankiss.", progress = "Some find strength in numbers. I respect this idea, when it is properly executed.", completion = "Superb! What a battle!\n\nYou have proven yourself champion of this day's tournament. Well done!\n\nYou must return and put on such a show of strength in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[30910] = { id = 30910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greenstone Village", description = "Please help!\n\nWe paid some adventurers to run off all the elemental spirits and now they're back for revenge!", sourceObjective = "Rescue all the villagers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30918] = { id = 30918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hui's Vengeance", description = "I am ashamed to ask, but for Greenstone's sake... might we now trouble you to face Vengeful Hui on our behalf...?", sourceObjective = "Defeat Vengeful Hui.", sourceObjectiveStatus = "unverified-source-field" }
quests[30921] = { id = 30921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Motives of the Mantid", description = "{class}. You may be of assistance.\n\nThe Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them.\n\nThat's where you come in.\n\nI need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.", sourceObjective = "Slay mantid in Kri'vess so Tai Ho can look for clues on their bodies.", completion = "The abundance of yak hair on that mantid's body suggests one thing... it came from Niuzao Temple. Our journey continues westward, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30922] = { id = 30922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Antiseptic", description = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something.\n\nLet me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.", sourceObjective = "Obtain 5 Full Mushan Bladders.", progress = "It's messy work, certainly.\n\nNowhere near as messy as digging graves.", completion = "Your messy work may have saved a few lives today, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30923] = { id = 30923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set the Mantid Back", description = "Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back.\n\n<Tai Ho hands you some explosives.>\n\nI need to keep a low profile. Would you do the honors?", sourceObjective = "Use Gunpowder Casks to explode the Kri'thik Weapons and the Kri'thik Supplies in Kri'vess.", completion = "We are in your debt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30924] = { id = 30924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisdom of Niuzao", description = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking.\n\nHe may, in fact, know much more than that.\n\nI will rendezvous with you at Niuzao Temple, {class}.", sourceObjective = "Speak with Ogo the Younger at Niuzao Temple in the Townlong Steppes.", completion = "Your Shado-Pan associate has spoken with me. Yes, Niuzao knows why the mantid are attacking. But he is not ready to tell you.\n\nNot yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30925] = { id = 30925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niuzao's Price", description = "Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north.\n\nBring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.", sourceObjective = "Kill the mantid of the Sra'thik Incursion so that Tai Ho can search their bodies for pieces of Niuzao's statuette.", progress = "Niuzao does not move quickly, nor does he make rash decisions. Perform his task, and give him time to decide.", completion = "Niuzao will be pleased.\n\nDespite his size, our patron is a beast of grace and compassion. He treasured this icon... just as he treasures each of his followers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30926] = { id = 30926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrible Truth", description = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear.\n\nIt was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now.\n\nSee for yourself. The mantid burrowed into the western side of our island.", sourceObjective = "Investigate the Niuzao Catacombs, then slay the Dread Shadow that dwells within.", completion = "Let me make this clear... that creature was NOT the Sha of Fear. Simply a shadow... a fraction of the sha's true power.\n\nNo, the Sha of Fear is with the mantid now. The elders of my order need to be informed of this immediately.\n\nI will handle the rest from here. Thank you for your assistance, {race}. Once again, your kind proves to be an asset to Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[30927] = { id = 30927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Them Peace", description = "I overheard. Our secret is out, then.\n\nWhen I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned.\n\nA pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, {name}. Give them the peace they deserve.", sourceObjective = "Give peace to 10 Fear-Stricken Sentinels by closing their eyes and placing them on their bellies.", progress = "I should have gone with them.", completion = "Thank you, {class}.\n\n\n\nI should have been among them.", sourceObjectiveStatus = "unverified-source-field" }
quests[30928] = { id = 30928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trail of Fear", description = "You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it.\n\nThe Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.", sourceObjective = "Kill 12 Dreadlings within the Niuzao Catacombs.", progress = "Even among our own order, only a few chosen elders knew of our sacred duty to contain the Sha of Fear.\n\nWhy they chose to tell the yak-keeper, I may never know.", completion = "We already have mantid, mogu, and yaungol to worry about. This sha problem needs to be nipped in the bud before even we are overrun.", sourceObjectiveStatus = "unverified-source-field" }
quests[30929] = { id = 30929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Yak", description = "Is this the place where they replace defective yaks?\n\nCan anybody help me out, here?", sourceObjective = "Help Bluesaddle replace his defective yak.", progress = "This yak is not a good yak. Not at all.", completion = "I think we made a pretty convincing argument. They'll HAVE to replace my yak now.", sourceObjectiveStatus = "unverified-source-field" }
quests[30930] = { id = 30930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick a Yak", description = "I can't find a single good yak here. ALL the yaks are bad!\n\nSome are too stinky, some too fight-y, others just scared.\n\nYou look like a lucky {race}. Here, take a lasso. See if you can find a good yak for me.", sourceObjective = "Use the Yak Lasso on Wild Townlong Yaks, then fight against them to see if they are suitable for Bluesaddle.", progress = "See? I told you! No good yaks.", completion = "Well, well! A good yak!\n\nTell you what, {name}. I take this GOOD yak, and you can do whatever you want with this bad, bad one.", sourceObjectiveStatus = "unverified-source-field" }
quests[30931] = { id = 30931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Father's Crossbow", description = "I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen.\n\nIt was a mantid, walking right past me, carrying my father's crossbow.\n\nSomething's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.", sourceObjective = "Obtain Ku-Yao's Crossbow.", progress = "Did... did you find it?", completion = "Yeah, this is dad's.\n\nLet's head on over to the temple. They'll know what...\n\n<Ku-Mo's voice catches.>\n\n...what happened to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[30932] = { id = 30932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Father's Footsteps", description = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days.\n\nYou're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.", sourceObjective = "Find Father's Bedroll, Father's Shield, Ha-Cha, and Sentinel Yalo.", progress = "Any luck?", completion = "No shield, no crossbow, no yak... something bad has happened to dad.", sourceObjectiveStatus = "unverified-source-field" }
quests[30933] = { id = 30933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Father", description = "I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK.\n\nI've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?", sourceObjective = "Search for Sentinel Ku-Yao.", progress = "I know he's OK.", completion = "<Ku-Mo doesn't seem to notice you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30935] = { id = 30935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisherman's Tale", description = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know.\n\nMishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders.\n\nFollow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.", sourceObjective = "Speak with Mishi to travel to the Path of Conquerors. From there find Shin Whispercloud at Whispercloud Rise.", completion = "The elders have agreed to help us figure out where the Zandalari have hidden the Thunder King's remains.\n\nThey have a few conditions though...", sourceObjectiveStatus = "unverified-source-field" }
quests[30942] = { id = 30942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make A Fighter Out of Me", description = "Shhh! Don't speak so loudly! My father might hear you.\n\n<Shomi gestures to Steelbender Doshu.>\n\nMy father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet.\n\nThat's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise!\n\nPleaseeeeee!\n\nIf we get separated I'll meet you back in the village.", sourceObjective = "Kill 4 Amani Skirmishers, 4 Gurubashi Hexxers, and 3 Drakkari Frostweavers in Zouchin Province.", progress = "I'll show my father he's wrong about me!", completion = "I told you I was a fast learner! I will head back to the village to start training others. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30943] = { id = 30943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handle With Care", description = "I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage.\n\nThere is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture.\n\nThe plant you are looking for is appropriately named volatile bloom. Handle it with care, {class}.", sourceObjective = "Bring Elder Shu 50 Volatile Blooms.", progress = "Were you able to find a suitable amount of volatile blooms?", completion = "These are perfect! Now, I would go wash your hands a few times {class}.\n\nI would also continue to avoid open flames for a few days...", sourceObjectiveStatus = "unverified-source-field" }
quests[30944] = { id = 30944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes A Village", description = "The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured.\n\nIf the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job.\n\nRelieve them of their posts so that they might have time to heal and see their families.\n\nYou'll find them stationed around the village.", sourceObjective = "Relieve the Exhausted Defenders from their guard posts.", progress = "Are the villagers recovering?", completion = "Very good, {class}! With the villagers rested we may yet stand a chance against the Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30945] = { id = 30945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Yours Is Mine", description = "The elders want us to mount a defense? We're not monks, {class}; we need weapons if we hope to fight!\n\nScavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with.\n\nBring me as many as you can carry and I'll take care of the rest.", sourceObjective = "Retrieve 6 Stolen Weapons from the Zandalari Invaders.", progress = "We'll need more than luck to get us through this. I hope you found something I can work with.", completion = "Well, these are better than I had anticipated! I can make four spears for every one of their blades.\n\nDon't you worry, I'll make sure the villagers are armed when the time comes.", sourceObjectiveStatus = "unverified-source-field" }
quests[30946] = { id = 30946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revelations", description = "The prisoner is being kept upstairs, {name}. It will be difficult to get information from him, but even the slightest detail about their location will help.\n\nThe elders have begun questioning him already. With their help we should be able to figure out our next move.\n\nGo speak with him and see if he has any useful information.", sourceObjective = "Speak with the Zandalari Prisoner.", progress = "What did the prisoner have to say?", completion = "We cannot dwell on this setback, {name}. Prophet Khar'zul must be dealt with.\n\nEvery member of the Thunder King's forces we are able to destroy brings us one step closer to victory.", sourceObjectiveStatus = "unverified-source-field" }
quests[30952] = { id = 30952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unending Siege", description = "The mantid continue to attack us. Their numbers ebb and flow, but they do not stop.\n\nIt is no matter. The yak is stamina embodied. We will not bend to them.  We will defend his home forever.\n\nWill you help us?", sourceObjective = "Defeat 12 Sra'thik attackers at Niuzao Temple.", completion = "You fight like you are one of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[30953] = { id = 30953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Sentinels", description = "Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities.\n\nPlease, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.", sourceObjective = "Heal 8 Wounded Niuzao Sentinels above 50% health. You may use the Yak's Milk Flasks or your own healing spells and abilities.", progress = "Things look grim out there.", completion = "In times like these, we must trust in the power and protection of Niuzao. Should things get any worse, he will protect us.\n\nHe always does.", sourceObjectiveStatus = "unverified-source-field" }
quests[30954] = { id = 30954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade is a Blade", description = "This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them.\n\nIt is time to fight smart.\n\nMany of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.", sourceObjective = "Obtain 10 Sra'thik Weapons.", progress = "Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.", completion = "I will see to it that these are properly distributed. What's more - I'll make sure our blacksmiths get a rest. Niuzao knows they deserve it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30955] = { id = 30955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paying Tribute", description = "Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down.\n\nThe easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime.\n\nI will send one of my strongarms with you, to shoulder the load.", sourceObjective = "Obtain 6 stores of Niuzao Food. Your Niuzao Strongarm will carry the food for you.", progress = "Niuzao, please... it is time to join the battle...", completion = "He will get up. Soon. Maybe not today, but soon.\n\nAnd when he does...\n\n<A smile grows on Paosha's face.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30956] = { id = 30956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siege Swells", description = "Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle.\n\nHelp him, {class}. Return to the courtyard, and join in the defense of our temple.", sourceObjective = "Defeat 25 Sra'thik attackers at Niuzao Temple.", completion = "Look at him, {class}.\n\nNothing can stop Niuzao. Only Niuzao can stop Niuzao.", sourceObjectiveStatus = "unverified-source-field" }
quests[30957] = { id = 30957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Overwhelming Swarm", description = "I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm.\n\nThe kunchong, however, are something different.\n\nThey are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.", sourceObjective = "Defeat 4 Sra'thik Kunchong.", progress = "Stay stalwart, {race}. The kunchong would have their way with you.", completion = "Put on our armor, and you'd be indistinguishable from any of the other sentinels out there.\n\nGood fighting, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30958] = { id = 30958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Battle's Shadow", description = "Niuzao's appearance on the battlefield is a blessing... in more ways than one.\n\nWith the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help.\n\nToss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.", sourceObjective = "Throw 10 Loose Stones up to Niuzao Stonemasons.", progress = "I recommend you move with haste. Niuzao's distraction will not last forever.", completion = "It looks like the walls are beginning to take shape again. In time, the Temple will be whole again.", sourceObjectiveStatus = "unverified-source-field" }
quests[30959] = { id = 30959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Guns", description = "The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster.\n\n<Ogo hands you a few small casks of hastily-packed explosives.>\n\nBeware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.", sourceObjective = "Destroy 3 Sra'thik War Wagons.", progress = "We can push these mantid back. We can outlast them.", completion = "Good, you're back in one piece.\n\nWe hope to be seeing more of you in the future, {race}.", sourceObjectiveStatus = "unverified-source-field" }
